export type CandleWindowPoint = {
  readonly close: number;
  readonly high: number;
  readonly low: number;
  readonly open: number;
};

const MIN_RELATIVE_PRICE_SPAN = 0.000001;
const MIN_ABSOLUTE_PRICE_SPAN = 0.00000001;

export function hasMeaningfulCandleVariation(
  candles: readonly CandleWindowPoint[],
  minimumCandles: number = 3,
): boolean {
  const window = candles.slice(-safeMinimumCandles(minimumCandles));
  if (window.length < safeMinimumCandles(minimumCandles)) return false;
  const envelope = candleWindowEnvelope(window);
  if (envelope === null) return false;
  return envelope.span > minimumMeaningfulSpan(envelope.referencePrice);
}

export function candleWindowEnvelope(
  candles: readonly CandleWindowPoint[],
): { readonly referencePrice: number; readonly span: number } | null {
  let min = Number.POSITIVE_INFINITY;
  let max = Number.NEGATIVE_INFINITY;
  for (const candle of candles) {
    const bounds = candleBounds(candle);
    if (bounds === null) continue;
    min = Math.min(min, bounds.low);
    max = Math.max(max, bounds.high);
  }
  if (!Number.isFinite(min) || !Number.isFinite(max)) return null;
  return {
    referencePrice: Math.max(Math.abs(max), Math.abs(min), 1),
    span: max - min,
  };
}

function candleBounds(
  candle: CandleWindowPoint,
): { readonly high: number; readonly low: number } | null {
  const values = [candle.open, candle.high, candle.low, candle.close];
  if (!values.every(Number.isFinite)) return null;
  return { high: Math.max(...values), low: Math.min(...values) };
}

function minimumMeaningfulSpan(referencePrice: number): number {
  return Math.max(
    MIN_ABSOLUTE_PRICE_SPAN,
    Math.abs(referencePrice) * MIN_RELATIVE_PRICE_SPAN,
  );
}

function safeMinimumCandles(value: number): number {
  return Number.isFinite(value) ? Math.max(1, Math.floor(value)) : 1;
}

