import type { ChartCandle } from "./types";
import { hasMeaningfulCandleVariation } from "./candle-window-quality";
import {
  readJson,
  removeKey,
  sessionBrowserStorage,
  writeJson,
} from "@/lib/storage/browser-storage";

type StoredLiveCandleSeed = {
  readonly candles: readonly ChartCandle[];
  readonly storedAtMs: number;
  readonly version: 1;
};

const SESSION_PREFIX = "quartel.live-candles.v1";
const SESSION_TTL_MS = 120_000;
const SESSION_MIN_CANDLES = 3;

export function liveCandleSessionKey(
  symbol: string,
  intervalSeconds: number,
  maxCandles: number,
): string {
  return `${SESSION_PREFIX}:${symbol}:${intervalSeconds}:${maxCandles}`;
}

export function readLiveCandleSessionSeed(
  key: string,
  nowMs: number = Date.now(),
): ChartCandle[] {
  const payload = readJson<StoredLiveCandleSeed>(sessionBrowserStorage(), key);
  if (!isFreshStoredSeed(payload, nowMs)) {
    removeKey(sessionBrowserStorage(), key);
    return [];
  }
  return payload.candles.map((candle) => ({ ...candle }));
}

export function selectLiveCandleReloadSeed(
  initialCandles: readonly ChartCandle[] | undefined,
  sessionCandles: readonly ChartCandle[],
): readonly ChartCandle[] | undefined {
  if (hasMeaningfulCandleVariation(initialCandles ?? [], SESSION_MIN_CANDLES)) {
    return initialCandles;
  }
  if (!initialCandles?.length) return initialCandles;
  if (sessionCandles.length > 0) return sessionCandles;
  return initialCandles;
}

export function writeLiveCandleSessionSeed(
  key: string,
  candles: readonly ChartCandle[],
  nowMs: number = Date.now(),
): void {
  if (!hasMeaningfulCandleVariation(candles, SESSION_MIN_CANDLES)) return;
  writeJson<StoredLiveCandleSeed>(sessionBrowserStorage(), key, {
    candles: candles.map((candle) => ({ ...candle })),
    storedAtMs: nowMs,
    version: 1,
  });
}

function isFreshStoredSeed(
  payload: StoredLiveCandleSeed | null,
  nowMs: number,
): payload is StoredLiveCandleSeed {
  if (!isStoredSeed(payload)) return false;
  if (nowMs - payload.storedAtMs > SESSION_TTL_MS) return false;
  return hasMeaningfulCandleVariation(payload.candles, SESSION_MIN_CANDLES);
}

function isStoredSeed(
  value: StoredLiveCandleSeed | null,
): value is StoredLiveCandleSeed {
  if (value?.version !== 1 || !Array.isArray(value.candles)) return false;
  if (!Number.isFinite(value.storedAtMs)) return false;
  return value.candles.every(isChartCandle);
}

function isChartCandle(value: unknown): value is ChartCandle {
  if (typeof value !== "object" || value === null) return false;
  const candle = value as Record<string, unknown>;
  return ["time", "value", "open", "high", "low", "close"].every((key) =>
    Number.isFinite(candle[key]),
  );
}

