// Pure gate helpers extracted from RobotLegacyTradeCard.tsx so they can be
// unit tested without rendering the full card component.
import { toLegacyMiniChartData } from "@/components/trade/trade-card-mini-chart-core";
import { hasMeaningfulCandleVariation } from "@/features/trade/candle-window-quality";
import type { ChartCandle } from "@/features/trade/types";

export const LEGACY_ACTIVE_TRADE_COUNTBACK = 50;
export const LEGACY_ACTIVE_TRADE_CANDLES = 30;
// R280: 15 → 10. Operador queria mais zoom (paridade legacy). 10 candles
// visíveis dão ~50% mais largura por candle no viewport mobile sem perder
// contexto (o buffer LEGACY_ACTIVE_TRADE_CANDLES=30 segue igual).
export const LEGACY_ACTIVE_TRADE_VISIBLE = 10;
// Legacy parity (P4 Track E): the embedded active-trade mini chart drops to 3.
// The terminal/drawer chart below keeps the 50-candle requirement.
// Source: quartel-bot/lib/constants/candle-thresholds.ts:23
//   `const MIN_CANDLES_FOR_TRADE_CHART = 3`
export const MIN_ROBOT_TRADE_CHART_CANDLES = 3;
export const MIN_TRADE_CHART_CANDLES = MIN_ROBOT_TRADE_CHART_CANDLES;
export const ROBOT_TRADE_FIRST_PAINT_CANDLES = MIN_ROBOT_TRADE_CHART_CANDLES;

/** True when historical candles cover the full countback window. */
export function hasCompleteRobotTradeHistory(
  candles: readonly ChartCandle[],
): boolean {
  return candles.length >= LEGACY_ACTIVE_TRADE_COUNTBACK;
}

/** True when post-normalization candle count meets the mini chart minimum.
 *
 * Counts via `countRenderableMiniCandles` so parent gate and chart gate
 * use the same post-normalization threshold — closes Leak H5.
 *
 * Example: `hasCompleteRobotTradeCandles(liveCandles)` returns true at 3 normalized.
 */
export function hasCompleteRobotTradeCandles(
  candles: readonly ChartCandle[],
): boolean {
  const normalized = toLegacyMiniChartData(
    candles,
    LEGACY_ACTIVE_TRADE_CANDLES,
    LEGACY_ACTIVE_TRADE_CANDLES,
  );
  if (normalized.length < ROBOT_TRADE_FIRST_PAINT_CANDLES) return false;
  return hasMeaningfulCandleVariation(
    normalized,
    ROBOT_TRADE_FIRST_PAINT_CANDLES,
  );
}

/** Select the candle window to pass to the chart.
 *
 * Prefers live SSE candles once the first-paint threshold exists; otherwise
 * falls back to the historical tail. This keeps one-candle windows hidden
 * without leaving a live trade blank until the complete mini window arrives.
 *
 * Example: `stableActiveTradeCandles(live30, fallback)` returns `live30`.
 */
export function stableActiveTradeCandles(
  liveCandles: readonly ChartCandle[],
  fallbackCandles: readonly ChartCandle[],
): ChartCandle[] {
  if (hasCompleteRobotTradeCandles(liveCandles)) return [...liveCandles];
  if (!hasCompleteRobotTradeCandles(fallbackCandles)) {
    return [];
  }
  return fallbackCandles.slice(-LEGACY_ACTIVE_TRADE_CANDLES);
}

/** Select the candle window for the technical terminal drawer.
 *
 * Example: `stableTerminalTradeCandles(fallback)` returns `fallback` when complete.
 */
export function stableTerminalTradeCandles(
  fallbackCandles: readonly ChartCandle[],
): ChartCandle[] {
  if (hasCompleteRobotTradeHistory(fallbackCandles))
    return [...fallbackCandles];
  return [];
}

