// ActiveTradeCard — pending trade with countdown and (post-settlement)
// payout. Mirrors v1's slot in /trade visually: dark surface, glow ring
// per direction. Countdown ticks locally each second; SSE settlement event
// flips the card to its terminal state via cache invalidation.
import { useEffect, useRef, useState, type JSX } from "react";
import {
  TradeCardMiniVisuals,
  type TradeMiniOutcome,
} from "@/components/trade/TradeCardMiniVisuals";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import {
  useCandles,
  useGoptionLiveCandles,
  type UseCandlesOptions,
} from "../hooks";
import type { ChartCandle, TradeView } from "../types";
import { chartDebug } from "@/lib/observability/chart-debug";
import {
  ACTIVE_TRADE_CANDLE_COUNTBACK,
  ACTIVE_TRADE_MINI_CANDLES,
  MIN_TRADE_CHART_CANDLES,
  activeTradeChartCandles,
  hasCompleteActiveTradeChart,
  hasCompleteActiveTradeHistory,
} from "./active-trade-chart-gates";
import { ActiveTradeAssetIcon } from "./active-trade-asset-icon";
import { MiniTradeBadges } from "@/components/trade/MiniTradeBadges";

interface ActiveTradeCardProps {
  trade: TradeView | null | undefined;
}

type ActiveTradeMarketSnapshot = {
  readonly candles: ReturnType<typeof useCandles>["candles"];
  readonly currentPrice: number | undefined;
  readonly entryPrice: number | undefined;
  readonly isLoading: boolean;
  /** True when the chart is showing the frozen last window (post-settle).
   * Consumers can render an overlay/tint to mirror legacy `getFrozenChartClass`. */
  readonly isFrozen: boolean;
};

export function ActiveTradeCard({ trade }: ActiveTradeCardProps): JSX.Element {
  if (!trade) return <EmptyState />;
  return <ActiveTradeContent trade={trade} />;
}

// 2 s polling matches the legacy DEV chart cadence for active trades (P0-89).
const ACTIVE_TRADE_CANDLES_POLL_MS = 2_000;

function ActiveTradeContent({ trade }: { trade: TradeView }): JSX.Element {
  const market = useActiveTradeMarketSnapshot(trade);
  return (
    <Card
      className={`overflow-hidden border-white/10 bg-[#070B0E]/96 ${activeTradeDirectionGlow(trade)}`}
      data-testid="active-trade-card"
      data-asset={trade.asset}
    >
      <ActiveTradeHeader trade={trade} />
      <CardContent className="space-y-3 p-4 pt-2">
        <TradeProgress trade={trade} />
        <ActiveTradeMiniVisuals
          candles={market.candles}
          currentPrice={market.currentPrice}
          entryPrice={market.entryPrice}
          isFrozen={market.isFrozen}
          isLoading={market.isLoading}
          trade={trade}
        />
        <AmountRow trade={trade} />
        <CountdownRow trade={trade} />
        <SettlementRow trade={trade} />
      </CardContent>
    </Card>
  );
}

function useActiveTradeMarketSnapshot(
  trade: TradeView,
): ActiveTradeMarketSnapshot {
  const isPending = trade.status === "pending";
  const historical = useCandles(
    trade.asset,
    "1m",
    ACTIVE_TRADE_CANDLE_COUNTBACK,
    activeTradeCandleOptions(isPending),
  );
  const hasHistoricalSeed = hasCompleteActiveTradeHistory(historical.candles);
  // C-6 (#69) F-mini-chart: keep live SSE active regardless of trade status.
  // Disabling on settle (isPending=false) cleared live.candles, then
  // `activeTradeChartCandles` fell back to historical which may also be empty
  // when ACTIVE_TRADE_MINI_CANDLES post-normalization isn't met → chart
  // disappeared mid-flight. Keep live ticks streaming until the card unmounts.
  //
  // Snapshot+delta (28/05/2026): SSE opens IMMEDIATELY when we have a symbol
  // — no longer gated on `hasHistoricalSeed`. Ticks emitted during the REST
  // round-trip are buffered inside `useGoptionLiveCandles` and replayed onto
  // the seed when it lands, so the first paint has zero gap between history
  // and live. WHY: legacy serial REST→SSE wiring dropped ticks from the
  // ~1500ms boot window, which is exactly the "vela começa ruim e arruma"
  // bug the operator reported.
  const live = useGoptionLiveCandles(trade.asset, true, {
    initialCandles: hasHistoricalSeed ? historical.candles : [],
    intervalSeconds: 60,
    maxCandles: ACTIVE_TRADE_MINI_CANDLES,
    preserveReloadSeed: isPending,
  });
  const liveCandles = activeTradeChartCandles(live.candles, historical.candles);
  // F3 + G2 (#69-followup): freeze candles + price once the trade
  // settles. Extracted to keep this hook under the complexity budget.
  const { candles, currentPrice, isFrozen } = useFrozenChartSnapshot({
    isPending,
    liveCandles,
    livePrice: live.lastPrice,
    entryPrice: parseActiveTradeEntryPrice(trade.entryPrice),
  });
  chartDebug("parent-gate", {
    source: "ActiveTradeCard",
    symbol: trade.asset,
    liveLength: live.candles.length,
    fallbackLength: historical.candles.length,
    passingLength: candles.length,
    gateAction: hasCompleteActiveTradeChart(candles) ? "chart" : "pending",
  });
  const entryPrice = parseActiveTradeEntryPrice(trade.entryPrice);
  return {
    candles,
    currentPrice,
    entryPrice,
    isLoading: live.candles.length === 0 && historical.isLoading,
    isFrozen,
  };
}

function useFrozenChartSnapshot(params: {
  readonly isPending: boolean;
  readonly liveCandles: ChartCandle[];
  readonly livePrice: number | null;
  readonly entryPrice: number | undefined;
}): {
  readonly candles: ChartCandle[];
  readonly currentPrice: number | undefined;
  readonly isFrozen: boolean;
} {
  const frozenCandlesRef = useRef<ChartCandle[]>([]);
  const frozenPriceRef = useRef<number | undefined>(undefined);
  if (params.isPending && params.liveCandles.length > 0) {
    frozenCandlesRef.current = params.liveCandles;
  }
  const derivedPrice =
    params.livePrice ??
    params.liveCandles[params.liveCandles.length - 1]?.close ??
    params.entryPrice;
  if (params.isPending && derivedPrice !== undefined) {
    frozenPriceRef.current = derivedPrice;
  }
  const isFrozen = !params.isPending && frozenCandlesRef.current.length > 0;
  const candles = isFrozen ? frozenCandlesRef.current : params.liveCandles;
  const currentPrice =
    isFrozen && frozenPriceRef.current !== undefined
      ? frozenPriceRef.current
      : derivedPrice;
  return { candles, currentPrice, isFrozen };
}

function ActiveTradeHeader({
  trade,
}: {
  readonly trade: TradeView;
}): JSX.Element {
  return (
    <CardHeader className="p-4 pb-2">
      <CardTitle className="flex items-center justify-between text-sm">
        <span className="flex items-center gap-2 text-white">
          <ActiveTradeAssetIcon asset={trade.asset} />
          {trade.asset}
        </span>
        <DirectionBadge direction={trade.direction} />
      </CardTitle>
    </CardHeader>
  );
}

function activeTradeDirectionGlow(trade: TradeView): string {
  if (trade.direction === "CALL")
    return "shadow-[0_0_34px_rgba(0,255,148,0.08)]";
  return "shadow-[0_0_34px_rgba(239,68,68,0.08)]";
}

function ActiveTradeMiniVisuals(props: {
  readonly candles: ReturnType<typeof useCandles>["candles"];
  readonly currentPrice: number | undefined;
  readonly entryPrice: number | undefined;
  readonly isFrozen: boolean;
  readonly isLoading: boolean;
  readonly trade: TradeView;
}): JSX.Element {
  // `mini-chart` (NEW-XI-52) wraps the direction legend + chart so the
  // VENDA/COMPRA labels render exactly once whenever the card mounts —
  // independent of candle-completeness gating below.
  return (
    <div data-testid="mini-chart" className="space-y-3">
      <MiniTradeBadges direction={props.trade.direction} />
      <ActiveTradeChartSurface {...props} />
    </div>
  );
}

function ActiveTradeChartSurface(props: {
  readonly candles: ReturnType<typeof useCandles>["candles"];
  readonly currentPrice: number | undefined;
  readonly entryPrice: number | undefined;
  readonly isFrozen: boolean;
  readonly isLoading: boolean;
  readonly trade: TradeView;
}): JSX.Element {
  // F3 (#69-followup): once the trade settles and `isFrozen` flips on,
  // never fall back to the `Carregando mercado...` placeholder even if
  // the candles array is briefly incomplete — keep the last frozen
  // window visible so the result overlay shows ON TOP of the chart,
  // not inside an empty placeholder.
  if (!hasCompleteActiveTradeChart(props.candles) && !props.isFrozen) {
    return (
      <div
        data-testid="active-trade-chart-pending"
        className="py-8 text-center text-xs text-white/36"
      >
        Carregando mercado...
      </div>
    );
  }
  // The inner `TradeCardMiniChart` already exposes `active-trade-chart`;
  // we only add a wrapper element when frozen, so the freeze testid
  // doesn't collide with the inner chart testid.
  if (props.isFrozen) {
    return (
      <div
        data-testid="active-trade-chart-frozen"
        className="opacity-70 transition-opacity"
      >
        <TradeCardMiniVisuals
          assetSymbol={props.trade.asset}
          candles={props.candles}
          currentPrice={props.currentPrice}
          direction={props.trade.direction}
          entryLabel={entryLabel(props.trade)}
          entryPrice={props.entryPrice}
          isCandlesLoading={props.isLoading}
          lossValue={props.trade.status === "loss" ? "1" : "0"}
          minimumCandles={MIN_TRADE_CHART_CANDLES}
          outcome={tradeOutcome(props.trade)}
          payoutLabel={tradePayoutLabel(props.trade)}
          scoreValue={tradeConfidenceLabel(props.trade)}
          showOverlay={props.trade.status !== "pending"}
          winValue={props.trade.status === "win" ? "1" : "0"}
        />
      </div>
    );
  }
  return (
    <TradeCardMiniVisuals
      assetSymbol={props.trade.asset}
      candles={props.candles}
      currentPrice={props.currentPrice}
      direction={props.trade.direction}
      entryLabel={entryLabel(props.trade)}
      entryPrice={props.entryPrice}
      isCandlesLoading={props.isLoading}
      lossValue={props.trade.status === "loss" ? "1" : "0"}
      minimumCandles={MIN_TRADE_CHART_CANDLES}
      outcome={tradeOutcome(props.trade)}
      payoutLabel={tradePayoutLabel(props.trade)}
      scoreValue={tradeConfidenceLabel(props.trade)}
      showOverlay={props.trade.status !== "pending"}
      winValue={props.trade.status === "win" ? "1" : "0"}
    />
  );
}

function activeTradeCandleOptions(isPending: boolean): UseCandlesOptions {
  if (!isPending) return { realtime: true };
  return { refetchIntervalMs: ACTIVE_TRADE_CANDLES_POLL_MS, realtime: true };
}

function entryLabel(trade: TradeView): string {
  return trade.entryPrice
    ? `${trade.asset}: $${trade.entryPrice}`
    : `Entrada ${trade.direction}`;
}

function parseActiveTradeEntryPrice(
  value: TradeView["entryPrice"],
): number | undefined {
  if (value == null) return undefined;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : undefined;
}

function EmptyState(): JSX.Element {
  return (
    <Card
      className="border-white/10 bg-[#070B0E]/90"
      data-testid="active-trade-empty"
    >
      <CardContent className="py-8 text-center text-sm text-white/38">
        <div className="mx-auto mb-3 flex h-12 w-12 items-center justify-center rounded-2xl border border-white/10 bg-white/[0.03]">
          <span className="h-2 w-2 rounded-full bg-white/35" />
        </div>
        Nenhum trade ativo
      </CardContent>
    </Card>
  );
}

function DirectionBadge({
  direction,
}: {
  direction: TradeView["direction"];
}): JSX.Element {
  const label = direction === "CALL" ? "Subir" : "Cair";
  const tone =
    direction === "CALL"
      ? "border-[#00FF94]/25 bg-[#00FF94]/12 text-[#00FF94]"
      : "border-red-400/25 bg-red-500/12 text-red-300";
  return (
    <Badge variant="outline" className={`gap-1.5 rounded-full ${tone}`}>
      {label}
    </Badge>
  );
}

function TradeProgress({ trade }: { trade: TradeView }): JSX.Element {
  const remaining = useCountdown(trade);
  const pct =
    trade.status === "pending"
      ? Math.max(8, Math.min(100, remaining * 1.67))
      : 100;
  return (
    <div className="overflow-hidden rounded-2xl border border-white/8 bg-black/30 p-3">
      <div className="mb-2 flex items-center justify-between text-[10px] uppercase tracking-[0.18em] text-white/42">
        <span>Status</span>
        <span data-testid="active-trade-status">{trade.status}</span>
      </div>
      <div className="h-2 overflow-hidden rounded-full bg-white/8">
        <div
          className="h-full rounded-full bg-[#00FF94] shadow-[0_0_14px_rgba(0,255,148,0.35)]"
          style={{ width: `${pct}%` }}
        />
      </div>
    </div>
  );
}

function AmountRow({ trade }: { trade: TradeView }): JSX.Element {
  return (
    <div className="flex items-center justify-between text-sm">
      <span className="text-white/45">Valor</span>
      <span className="font-mono font-bold text-white">R$ {trade.amount}</span>
    </div>
  );
}

function CountdownRow({ trade }: { trade: TradeView }): JSX.Element {
  const remaining = useCountdown(trade);
  if (trade.status !== "pending") return <></>;
  return (
    <div className="flex items-center justify-between text-sm">
      <span className="text-white/45">Tempo restante</span>
      <span
        className="font-mono font-bold text-[#00FF94]"
        data-testid="active-trade-countdown"
      >
        {remaining}s
      </span>
    </div>
  );
}

function SettlementRow({ trade }: { trade: TradeView }): JSX.Element {
  if (trade.status === "pending") return <></>;
  return (
    <div className="flex items-center justify-between text-sm">
      <span className="text-white/45">Resultado</span>
      <span className="font-mono font-bold text-white">
        {trade.status} — R$ {trade.payout ?? "0.00"}
      </span>
    </div>
  );
}

function tradeOutcome(trade: TradeView): TradeMiniOutcome {
  if (trade.status === "win" || trade.status === "loss") return trade.status;
  return "pending";
}

function tradeConfidenceLabel(trade: TradeView): string {
  const confidence = Number(trade.confidence);
  if (!Number.isFinite(confidence)) return "86";
  return `${Math.round(confidence)}`;
}

function tradePayoutLabel(trade: TradeView): string | undefined {
  if (trade.status !== "win" || !trade.payout) return undefined;
  return `R$ ${trade.payout}`;
}

function useCountdown(trade: TradeView): number {
  const expiresAtMs = computeExpiry(trade);
  const [now, setNow] = useState<number>(() => Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1_000);
    return () => clearInterval(id);
  }, []);
  if (!expiresAtMs) return 0;
  return Math.max(0, Math.ceil((expiresAtMs - now) / 1_000));
}

function computeExpiry(trade: TradeView): number | null {
  if (trade.expirationTimestamp) return Number(trade.expirationTimestamp);
  if (trade.serverExpirationTimestamp) {
    const ms = Date.parse(trade.serverExpirationTimestamp);
    return Number.isFinite(ms) ? ms : null;
  }
  return null;
}

