// Pure gate helpers extracted from ActiveTradeCard.tsx so they can be unit
// tested without rendering the full card component.
import { toLegacyMiniChartData } from "@/components/trade/trade-card-mini-chart-core";
import { hasMeaningfulCandleVariation } from "@/features/trade/candle-window-quality";
import type { ChartCandle } from "@/features/trade/types";

export const ACTIVE_TRADE_CANDLE_COUNTBACK = 50;
export const ACTIVE_TRADE_MINI_CANDLES = 30;
// Legacy parity (P4 Track E): paint as soon as 3 candles are renderable so the
// embedded mini chart shows historical context immediately. REST still asks
// for the full 50-candle window via ACTIVE_TRADE_CANDLE_COUNTBACK.
// Source: quartel-bot/lib/constants/candle-thresholds.ts:23
//   `const MIN_CANDLES_FOR_TRADE_CHART = 3`
export const MIN_TRADE_CHART_CANDLES = 3;
export const ACTIVE_TRADE_FIRST_PAINT_CANDLES = MIN_TRADE_CHART_CANDLES;

/** True when historical candles cover the full countback window. */
export function hasCompleteActiveTradeHistory(
  candles: readonly ChartCandle[],
): boolean {
  return candles.length >= ACTIVE_TRADE_CANDLE_COUNTBACK;
}

/** True when post-normalization candle count meets the mini chart minimum.
 *
 * Counts via `countRenderableMiniCandles` so parent gate and chart gate
 * use the same post-normalization threshold — closes Leak H5.
 *
 * Example: `hasCompleteActiveTradeChart(liveCandles)` returns true at 3 normalized.
 */
export function hasCompleteActiveTradeChart(
  candles: readonly ChartCandle[],
): boolean {
  const normalized = toLegacyMiniChartData(
    candles,
    ACTIVE_TRADE_MINI_CANDLES,
    ACTIVE_TRADE_MINI_CANDLES,
  );
  if (normalized.length < ACTIVE_TRADE_FIRST_PAINT_CANDLES) return false;
  return hasMeaningfulCandleVariation(
    normalized,
    ACTIVE_TRADE_FIRST_PAINT_CANDLES,
  );
}

/** Select the candle window to pass to the chart.
 *
 * Prefers live SSE candles once the first-paint threshold exists; otherwise
 * falls back to the historical tail. This prevents a one-candle chart while
 * avoiding a blank chart during live trades.
 *
 * Example: `activeTradeChartCandles(live30, historical)` returns `live30`.
 */
export function activeTradeChartCandles(
  liveCandles: readonly ChartCandle[],
  historicalCandles: readonly ChartCandle[],
): ChartCandle[] {
  if (hasCompleteActiveTradeChart(liveCandles)) return [...liveCandles];
  if (!hasCompleteActiveTradeChart(historicalCandles)) {
    return [];
  }
  return historicalCandles.slice(-ACTIVE_TRADE_MINI_CANDLES);
}

