import { render } from "@testing-library/react";
import { beforeEach, afterEach, describe, expect, it, vi } from "vitest";
import { TradeCardMiniChart } from "@/components/trade/TradeCardMiniChart";
import type { TradeMiniCandle } from "@/components/trade/trade-card-mini-chart-core";

const miniChartMocks = vi.hoisted(() => {
  const timeScaleApi = {
    getVisibleLogicalRange: vi.fn(() => ({ from: 0, to: 15 })),
    setVisibleLogicalRange: vi.fn(),
  };
  const seriesApi = {
    createPriceLine: vi.fn(() => ({ applyOptions: vi.fn() })),
    removePriceLine: vi.fn(),
    setData: vi.fn(),
    update: vi.fn(),
