describe("TradeCardMiniChart entry-line span contract", () => {
  beforeEach(() => {
    vi.spyOn(HTMLCanvasElement.prototype, "getContext").mockReturnValue(
      {} as CanvasRenderingContext2D,
    );
    // jsdom has no ResizeObserver; the price-label measure hook needs one.
    vi.stubGlobal("ResizeObserver", NoopResizeObserver);
    // Drive rAF synchronously so label state settles before assertions.
    vi.spyOn(window, "requestAnimationFrame").mockImplementation((cb) => {
      cb(0);
      return 1;
    });
    vi.spyOn(window, "cancelAnimationFrame").mockImplementation(
      () => undefined,
    );
    // jsdom containers report 0x0 — give them a measurable rect so the label
    // layout has a non-zero chart height to work with.
    vi.spyOn(
      HTMLDivElement.prototype,
      "getBoundingClientRect",
    ).mockImplementation(
      () =>
        ({
          height: 160,
          width: 320,
          x: 0,
          y: 0,
          top: 0,
          left: 0,
          right: 320,
          bottom: 160,
          toJSON: () => ({}),
        }) as DOMRect,
    );
    Object.defineProperty(HTMLDivElement.prototype, "clientHeight", {
      configurable: true,
      get: () => 160,
    });
    Object.defineProperty(HTMLDivElement.prototype, "clientWidth", {
      configurable: true,
      get: () => 320,
    });
    clearEntryLineMocks();
  });

  afterEach(() => {
    vi.restoreAllMocks();
    vi.unstubAllGlobals();
  });

  it("renders the entry line as a single dashed canvas line (createPriceLine call)", () => {
    render(
      <TradeCardMiniChart
        candles={buildCandles(10)}
        currentPrice={74_984}
        direction="PUT"
        entryPrice={75_000}
        minimumCandles={3}
      />,
    );

    // Exactly one entry-line createPriceLine call.
    expect(entryLineMocks.seriesApi.createPriceLine).toHaveBeenCalledTimes(1);

    const call = entryLineMocks.seriesApi.createPriceLine.mock.calls[0];
    if (!call) throw new Error("expected createPriceLine to be called");
    const lineOptions = (call as unknown as ReadonlyArray<unknown>)[0] as {
      readonly price: number;
      readonly lineStyle: number;
      readonly axisLabelVisible: boolean;
    };

    // Contract: line is anchored at the entry price, dashed, and MUST hide the
    // axis label — the right-side label is owned by the DOM pill instead so
    // the canvas line has nothing to truncate it.
    expect(lineOptions.price).toBe(75_000);
    expect(lineOptions.lineStyle).toBe(2);
    expect(lineOptions.axisLabelVisible).toBe(false);
  });

  it("does not render the deprecated mini-chart-entry-line DOM overlay", () => {
    render(
      <TradeCardMiniChart
        candles={buildCandles(10)}
        currentPrice={74_984}
        direction="PUT"
        entryPrice={75_000}
        minimumCandles={3}
      />,
    );

    expect(
      screen.queryByTestId("mini-chart-entry-line"),
    ).not.toBeInTheDocument();
  });

  it("renders the right-side DOM pills for entry and current price", async () => {
    render(
      <TradeCardMiniChart
        candles={buildCandles(10)}
        currentPrice={74_984}
        direction="PUT"
        entryPrice={75_000}
        minimumCandles={3}
      />,
    );

    // Pills are mounted via an effect that runs after `isCanvasVisible` flips
    // true (post-`setVisualReady`). Wait for both testids to appear instead of
    // asserting synchronously.
    await waitFor(() => {
      expect(
        screen.getByTestId("active-trade-price-label-entry"),
      ).toBeInTheDocument();
      expect(
        screen.getByTestId("active-trade-price-label-current"),
      ).toBeInTheDocument();
    });
  });

  it("keeps rightPriceScale.visible=true so candles don't invade the label band", () => {
    // R289: rightPriceScale stays VISIBLE so lightweight-charts reserves
    // the right-edge band where the DOM price-label pills sit — without
    // this, candles render under the pills (operator: "as velas tão
    // invadindo onde era o campo dos valores"). The dashed-line truncation
    // is bridged by a DOM continuation strip rendered behind the pills, NOT
    // by hiding the native scale.
    render(
      <TradeCardMiniChart
        candles={buildCandles(10)}
        currentPrice={74_984}
        direction="PUT"
        entryPrice={75_000}
        minimumCandles={3}
      />,
    );

    expect(entryLineMocks.createChart).toHaveBeenCalled();
    const createCall = entryLineMocks.createChart.mock.calls[0];
    expect(createCall).toBeDefined();
    const options = createCall![1] as {
      readonly rightPriceScale?: { readonly visible?: boolean };
    };

    expect(options.rightPriceScale).toBeDefined();
    // CONTRACT: native right scale stays visible (band reserved). If this
    // flips to `false`, the candle-invasion regression returns.
    expect(options.rightPriceScale?.visible).toBe(true);
  });

  it("renders DOM continuation strips behind each price pill so dashed line has no visual gap", async () => {
    // R289/R291: with rightPriceScale.visible=true, lightweight-charts
    // reserves a band on the right where `createPriceLine` doesn't draw.
    // Two DOM `<span>` strips (one per pill — entry yellow + current green)
    // bridge that band visually. If these strips ever disappear, the
    // operator-reported "vão entre linha de entrada e vela" regression
    // returns and this test fails.
    render(
      <TradeCardMiniChart
        candles={buildCandles(10)}
        currentPrice={74_984}
        direction="PUT"
        entryPrice={75_000}
        minimumCandles={3}
      />,
    );

    await waitFor(() => {
      expect(
        screen.getByTestId("active-trade-price-label-entry-line-extension"),
      ).toBeInTheDocument();
      expect(
        screen.getByTestId("active-trade-price-label-current-line-extension"),
      ).toBeInTheDocument();
    });

    const entryStrip = screen.getByTestId(
      "active-trade-price-label-entry-line-extension",
    );
    const currentStrip = screen.getByTestId(
      "active-trade-price-label-current-line-extension",
    );
    // Each strip MUST carry the dashed repeating-linear-gradient + the
    // tone color so a CSS regression that drops the dashes or recolors them
    // breaks this test.
    expect(entryStrip.style.backgroundImage).toContain(
      "repeating-linear-gradient",
    );
    expect(entryStrip.style.backgroundImage).toContain("#EAB308");
    expect(currentStrip.style.backgroundImage).toContain(
      "repeating-linear-gradient",
    );
    expect(currentStrip.style.backgroundImage).toContain("#00FF94");
    // R292: strip width matches the lightweight-charts band (~56px). Wider
    // would extend INTO the candle area and double up with the canvas line.
    // Lower than 40 would leave a visible gap between line end and pill.
    const entryWidthPx = Number.parseInt(entryStrip.style.width, 10);
    expect(entryWidthPx).toBeGreaterThanOrEqual(40);
    expect(entryWidthPx).toBeLessThanOrEqual(72);
  });

  it("hides the canvas until focusRecentCandles has applied (no initial flash)", async () => {
    // R294: the operator-reported regression — on first paint the chart
    // briefly showed all 30 candles unfocused (with empty space between the
    // last candle and the entry line) before `focusRecentCandles` applied
    // the 10-candle window. The fix gates canvas opacity-100 on
    // `isVisualReady || hasPaintedSnapshot`, which only flips after 2 RAFs
    // (post-focus). `isCompleteData` alone — which used to short-circuit
    // visibility — is no longer enough.
    render(
      <TradeCardMiniChart
        candles={buildCandles(10)}
        currentPrice={74_984}
        direction="PUT"
        entryPrice={75_000}
        minimumCandles={3}
      />,
    );

    // Wait for the visual ready gate to flip and apply opacity-100.
    await waitFor(() => {
      expect(screen.getByTestId("active-trade-chart")).toHaveAttribute(
        "data-visual-ready",
        "true",
      );
    });

    // Once visual-ready=true, the canvas wrapper exposes the chart and
    // focus has applied (we cannot inspect lightweight-charts internals
    // through the mock, but the gate is now equivalent to "focus done").
    expect(screen.getByTestId("active-trade-chart-canvas")).toBeInTheDocument();
  });

  it("canvas inner div starts opacity-0 and only flips to opacity-100 after focus settled", async () => {
    // R294 strong-guard: the operator demanded a hard regression test for
    // the candle-flash bug. The canvas's inner <div ref={containerRef}> is
    // the actual paint surface. Before `focusRecentCandles` + 2-RAF gate
    // settles, it MUST have opacity-0. Otherwise users see the unfocused
    // initial paint (all 30 candles squeezed, last candle far from entry
    // line) before the chart "fixes itself".
    render(
      <TradeCardMiniChart
        candles={buildCandles(10)}
        currentPrice={74_984}
        direction="PUT"
        entryPrice={75_000}
        minimumCandles={3}
      />,
    );

    // The canvas wrapper carries the test id; its only child is the
    // containerRef'd <div> with the opacity class.
    const canvasWrapper = screen.getByTestId("active-trade-chart-canvas");
    const innerCanvas = canvasWrapper.firstElementChild as HTMLElement | null;
    if (!innerCanvas) throw new Error("expected inner canvas div");

    await waitFor(() => {
      expect(innerCanvas.className).toContain("opacity-100");
    });
    // Sanity: never has opacity-0 once the focus has applied — we cannot
    // assert pre-flip in the same test because waitFor races the rAFs, but
    // we still pin the post-flip state so a regression that flips the
    // opacity logic backwards fails here.
    expect(innerCanvas.className).not.toContain("opacity-0");
  });

  it("MUST guarantee 1 createPriceLine call (no duplicate entry overlay) on first paint", async () => {
    // R294: extra paranoid guard — the deprecated DOM overlay
    // `mini-chart-entry-line` was removed because operators reported two
    // yellow lines. If a future change re-introduces a second
    // createPriceLine OR a DOM div with that testid, this guard blocks the
    // commit.
    render(
      <TradeCardMiniChart
        candles={buildCandles(10)}
        currentPrice={74_984}
        direction="PUT"
        entryPrice={75_000}
        minimumCandles={3}
      />,
    );

    await waitFor(() => {
      expect(
        screen.getByTestId("active-trade-chart-canvas"),
      ).toBeInTheDocument();
    });

    expect(entryLineMocks.seriesApi.createPriceLine).toHaveBeenCalledTimes(1);
    expect(
      screen.queryByTestId("mini-chart-entry-line"),
    ).not.toBeInTheDocument();
    // Both DOM continuation strips must exist — if either is missing, the
    // line truncates visibly before the pill (operator-reported gap).
    expect(
      screen.getByTestId("active-trade-price-label-entry-line-extension"),
    ).toBeInTheDocument();
    expect(
      screen.getByTestId("active-trade-price-label-current-line-extension"),
    ).toBeInTheDocument();
  });
});

