// Tests for ActiveTradeCard — empty state and pending trade rendering.
import { render, screen } from "@testing-library/react";
import { beforeEach, describe, it, expect, vi } from "vitest";
import { ActiveTradeCard } from "@/features/trade/components/ActiveTradeCard";
import type { ChartCandle, TradeView } from "@/features/trade/types";

type MockCandlesResult = {
  readonly candles: ChartCandle[];
  readonly isLoading: boolean;
};

type MockLiveCandlesResult = {
  readonly candles: ChartCandle[];
  readonly lastPrice: number | null;
};

const hookMocks = vi.hoisted(() => ({
  useCandles: vi.fn<() => MockCandlesResult>(() => ({
    candles: [],
    isLoading: false,
  })),
  useGoptionLiveCandles: vi.fn<() => MockLiveCandlesResult>(() => ({
    candles: [],
    lastPrice: null,
  })),
}));

const miniVisualsMock = vi.hoisted(() => ({
  TradeCardMiniVisuals: vi.fn((_props: unknown) => null),
}));

vi.mock("@/features/trade/hooks", () => ({
  useCandles: hookMocks.useCandles,
  useGoptionLiveCandles: hookMocks.useGoptionLiveCandles,
}));

vi.mock("@/components/trade/TradeCardMiniVisuals", () => ({
  TradeCardMiniVisuals: miniVisualsMock.TradeCardMiniVisuals,
}));

function makeTrade(overrides: Partial<TradeView> = {}): TradeView {
  return {
    id: "t1",
    asset: "BTCUSDT",
    direction: "CALL",
    status: "pending",
    amount: "10.00",
    payout: null,
    createdAt: "2026-01-01T12:00:00Z",
    tokenCost: 0,
    confidence: "86",
    entryPrice: null,
    expirationTimestamp: String(Date.now() + 60_000),
    serverExpirationTimestamp: null,
    martingaleGroupId: null,
    martingaleLevel: 0,
    ...overrides,
  } as TradeView;
}

function candleAt(index: number): ChartCandle {
  const close = 80_000 + index;
  return {
    close,
    high: close + 3,
    low: close - 3,
    open: close - 1,
    time: 1_700_000_000 + index * 60,
    value: close,
  };
}

function candlesOfLength(count: number): ChartCandle[] {
  return Array.from({ length: count }, (_, index) => candleAt(index));
}

describe("ActiveTradeCard", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    hookMocks.useCandles.mockReturnValue({ candles: [], isLoading: false });
    hookMocks.useGoptionLiveCandles.mockReturnValue({
      candles: [],
      lastPrice: null,
    });
  });

  it("renders empty state when trade is null", () => {
    render(<ActiveTradeCard trade={null} />);
    expect(screen.getByTestId("active-trade-empty")).toBeInTheDocument();
  });

  it("renders empty state when trade is undefined", () => {
    render(<ActiveTradeCard trade={undefined} />);
    expect(screen.getByTestId("active-trade-empty")).toBeInTheDocument();
  });

  it("renders active trade card when trade is provided", () => {
    render(<ActiveTradeCard trade={makeTrade()} />);
    expect(screen.getByTestId("active-trade-card")).toBeInTheDocument();
  });

  it("shows asset label in trade card", () => {
    render(<ActiveTradeCard trade={makeTrade()} />);
    expect(screen.getByText("BTCUSDT")).toBeInTheDocument();
  });

  it("shows Subir badge for CALL direction", () => {
    render(<ActiveTradeCard trade={makeTrade({ direction: "CALL" })} />);
    expect(screen.getByText("Subir")).toBeInTheDocument();
  });

  it("shows Cair badge for PUT direction", () => {
    render(<ActiveTradeCard trade={makeTrade({ direction: "PUT" })} />);
    expect(screen.getByText("Cair")).toBeInTheDocument();
  });

  it("shows trade status in progress row", () => {
    render(<ActiveTradeCard trade={makeTrade()} />);
    expect(screen.getByTestId("active-trade-status")).toBeInTheDocument();
  });

  it("shows countdown for pending status", () => {
    render(<ActiveTradeCard trade={makeTrade({ status: "pending" })} />);
    expect(screen.getByTestId("active-trade-countdown")).toBeInTheDocument();
  });

  it("requests 50 realtime candles but caps live mini-chart history at 30", () => {
    const historicalCandles = candlesOfLength(50);
    hookMocks.useCandles.mockReturnValue({
      candles: historicalCandles,
      isLoading: false,
    });
    render(<ActiveTradeCard trade={makeTrade({ status: "pending" })} />);
    expect(hookMocks.useCandles).toHaveBeenCalledWith("BTCUSDT", "1m", 50, {
      refetchIntervalMs: 2_000,
      realtime: true,
    });
    expect(hookMocks.useGoptionLiveCandles).toHaveBeenCalledWith(
      "BTCUSDT",
      true,
      expect.objectContaining({ maxCandles: 30 }),
    );
  });

  it("passes live current price, entry price, and asset identity to mini visuals", () => {
    hookMocks.useCandles.mockReturnValue({
      candles: candlesOfLength(50),
      isLoading: false,
    });
    hookMocks.useGoptionLiveCandles.mockReturnValue({
      candles: [],
      lastPrice: 3_155.5,
    });
    render(
      <ActiveTradeCard
        trade={makeTrade({ asset: "ETHUSDT", entryPrice: "3150" })}
      />,
    );

    const props = miniVisualsMock.TradeCardMiniVisuals.mock.calls[0]?.[0] as {
      readonly assetSymbol?: string;
      readonly currentPrice?: number;
      readonly entryPrice?: number;
    };
    expect(props).toMatchObject({
      assetSymbol: "ETHUSDT",
      currentPrice: 3_155.5,
      entryPrice: 3_150,
    });
  });

  it("keeps the chart unmounted while only a short history is available", () => {
    hookMocks.useCandles.mockReturnValue({
      candles: candlesOfLength(1),
      isLoading: false,
    });
    render(<ActiveTradeCard trade={makeTrade({ status: "pending" })} />);

    expect(
      screen.getByTestId("active-trade-chart-pending"),
    ).toBeInTheDocument();
    expect(miniVisualsMock.TradeCardMiniVisuals).not.toHaveBeenCalled();
    // Snapshot+delta (28/05/2026): SSE opens immediately even with a short
    // history. The hook itself buffers ticks until the seed lands, so the
    // parent now passes `enabled=true` regardless of historical seed
    // completeness (initialCandles still [] until ACTIVE_TRADE_MIN_HISTORY).
    expect(hookMocks.useGoptionLiveCandles).toHaveBeenCalledWith(
      "BTCUSDT",
      true,
      expect.objectContaining({ initialCandles: [] }),
    );
  });

  it("keeps pending when live returns one candle before history is ready", () => {
    hookMocks.useCandles.mockReturnValue({
      candles: candlesOfLength(2),
      isLoading: false,
    });
    hookMocks.useGoptionLiveCandles.mockReturnValue({
      candles: candlesOfLength(1),
      lastPrice: 80_000,
    });
    render(<ActiveTradeCard trade={makeTrade({ status: "pending" })} />);

    expect(
      screen.getByTestId("active-trade-chart-pending"),
    ).toBeInTheDocument();
    expect(miniVisualsMock.TradeCardMiniVisuals).not.toHaveBeenCalled();
  });

  it("renders only the last 30 candles after the 50-candle seed is complete", () => {
    hookMocks.useCandles.mockReturnValue({
      candles: candlesOfLength(50),
      isLoading: false,
    });
    render(<ActiveTradeCard trade={makeTrade({ status: "pending" })} />);

    const props = miniVisualsMock.TradeCardMiniVisuals.mock.calls[0]?.[0] as {
      readonly candles?: readonly ChartCandle[];
    };
    expect(screen.queryByTestId("active-trade-chart-pending")).toBeNull();
    expect(props.candles).toHaveLength(30);
    expect(props.candles?.[0]?.time).toBe(candleAt(20).time);
  });

  // C-6 (#69) F-mini-chart: pending → win transition must keep chart rendered.
  // Previously, settle disabled live SSE (isPending && hasHistoricalSeed →
  // false), live.candles emptied, gates returned [] and the chart vanished.
  // Now SSE stays enabled while card is mounted, so live.candles persist.
  it("keeps the chart rendered when trade transitions from pending to win", () => {
    hookMocks.useCandles.mockReturnValue({
      candles: candlesOfLength(50),
      isLoading: false,
    });
    hookMocks.useGoptionLiveCandles.mockReturnValue({
      candles: candlesOfLength(30),
      lastPrice: 80_010,
    });
    const { rerender } = render(
      <ActiveTradeCard trade={makeTrade({ status: "pending" })} />,
    );
    expect(screen.queryByTestId("active-trade-chart-pending")).toBeNull();
    rerender(<ActiveTradeCard trade={makeTrade({ status: "win" })} />);
    expect(screen.queryByTestId("active-trade-chart-pending")).toBeNull();
    // useGoptionLiveCandles must have been invoked with enabled=true even
    // for the settled (status != pending) render so the live tick stream
    // doesn't go dark and erase the chart mid-flight.
    const calls = hookMocks.useGoptionLiveCandles.mock
      .calls as unknown as Array<readonly [string, boolean, unknown]>;
    const lastCall = calls[calls.length - 1];
    expect(lastCall?.[1]).toBe(true);
  });

  // F3 (#69-followup): even when the live + historical sources both
  // transiently produce an INCOMPLETE candle window post-settle, the
  // chart must remain visible (frozen last-good window) rather than
  // falling back to the "Carregando mercado..." placeholder. Surface
  // the freeze with the `active-trade-chart-frozen` testid so e2e can
  // pin the behavior.
  it("freezes the last complete window and surfaces frozen testid after settle", () => {
    hookMocks.useCandles.mockReturnValue({
      candles: candlesOfLength(50),
      isLoading: false,
    });
    hookMocks.useGoptionLiveCandles.mockReturnValue({
      candles: candlesOfLength(30),
      lastPrice: 80_010,
    });
    const { rerender } = render(
      <ActiveTradeCard trade={makeTrade({ status: "pending" })} />,
    );
    // Now simulate post-settle: both sources go incomplete.
    hookMocks.useCandles.mockReturnValue({ candles: [], isLoading: false });
    hookMocks.useGoptionLiveCandles.mockReturnValue({
      candles: [],
      lastPrice: 80_020,
    });
    rerender(<ActiveTradeCard trade={makeTrade({ status: "win" })} />);
    // The placeholder MUST stay hidden; the frozen marker MUST appear.
    expect(screen.queryByTestId("active-trade-chart-pending")).toBeNull();
    expect(screen.getByTestId("active-trade-chart-frozen")).toBeInTheDocument();
  });

  // G2 (#69-followup): once isFrozen flips on, currentPrice must hold
  // the last pending value even though `live.lastPrice` keeps ticking.
  // Operator complaint: "mesmo depois que congela ainda muda análise
  // antes de mostrar o resultado".
  it("G2: pins currentPrice to the last pending live tick after settle", () => {
    hookMocks.useCandles.mockReturnValue({
      candles: candlesOfLength(50),
      isLoading: false,
    });
    hookMocks.useGoptionLiveCandles.mockReturnValue({
      candles: candlesOfLength(30),
      lastPrice: 80_010,
    });
    const { rerender } = render(
      <ActiveTradeCard trade={makeTrade({ status: "pending" })} />,
    );
    const pendingPrice = (
      miniVisualsMock.TradeCardMiniVisuals.mock.calls.at(-1)?.[0] as {
        readonly currentPrice?: number;
      }
    )?.currentPrice;
    expect(pendingPrice).toBe(80_010);

    // Settle. A late tick arrives with a different price — must NOT bleed
    // into the badge.
    hookMocks.useGoptionLiveCandles.mockReturnValue({
      candles: candlesOfLength(30),
      lastPrice: 99_999,
    });
    rerender(<ActiveTradeCard trade={makeTrade({ status: "win" })} />);
    const frozenPrice = (
      miniVisualsMock.TradeCardMiniVisuals.mock.calls.at(-1)?.[0] as {
        readonly currentPrice?: number;
      }
    )?.currentPrice;
    expect(frozenPrice).toBe(80_010);
  });
});

