// Tests for trade-card-mini-chart-core pure functions.
// lightweight-charts types are imported but the heavy canvas code never runs.
import { describe, it, expect } from "vitest";
import {
  hasCompleteMiniChartData,
  toLegacyMiniChartData,
  toValidMiniChartCandle,
  createLegacyMiniChartOptions,
  createLegacyMiniSeriesOptions,
  type TradeMiniCandle,
} from "@/components/trade/trade-card-mini-chart-core";

function makeCandle(overrides: Partial<TradeMiniCandle> = {}): TradeMiniCandle {
  return {
    time: 1_700_000_000,
    open: 1.1,
    high: 1.2,
    low: 1.0,
    close: 1.15,
    ...overrides,
  };
}

describe("toValidMiniChartCandle", () => {
  it("returns a CandlestickData for a well-formed candle", () => {
    const candle = makeCandle();
    const result = toValidMiniChartCandle(candle);
    expect(result).not.toBeNull();
    expect(result?.close).toBe(candle.close);
    expect(result?.open).toBe(candle.open);
    expect(result?.time).toBe(candle.time);
  });

  it("normalises high to max(high, open, close)", () => {
    const candle = makeCandle({ open: 1.3, high: 1.1, close: 1.25 });
    const result = toValidMiniChartCandle(candle);
    expect(result?.high).toBe(1.3);
  });

  it("normalises low to min(low, open, close)", () => {
    const candle = makeCandle({ open: 1.0, low: 1.1, close: 0.95 });
    const result = toValidMiniChartCandle(candle);
    expect(result?.low).toBe(0.95);
  });

  it("returns null when a value is NaN", () => {
    const candle = makeCandle({ close: NaN });
    expect(toValidMiniChartCandle(candle)).toBeNull();
  });

  it("returns null when a value is Infinity", () => {
    const candle = makeCandle({ high: Infinity });
    expect(toValidMiniChartCandle(candle)).toBeNull();
  });

  it("returns null when open is zero (not positive)", () => {
    const candle = makeCandle({ open: 0 });
    expect(toValidMiniChartCandle(candle)).toBeNull();
  });

  it("returns null when a value is negative", () => {
    const candle = makeCandle({ low: -0.5 });
    expect(toValidMiniChartCandle(candle)).toBeNull();
  });
});

describe("toLegacyMiniChartData", () => {
  it("returns empty array for empty input", () => {
    expect(toLegacyMiniChartData([], 50, 10)).toHaveLength(0);
  });

  it("returns valid candles for well-formed input", () => {
    const candles = [makeCandle({ time: 1 }), makeCandle({ time: 2 })];
    const result = toLegacyMiniChartData(candles, 50, 10);
    expect(result).toHaveLength(2);
  });

  it("slices to maxCandles from the end", () => {
    const candles = Array.from({ length: 10 }, (_, i) =>
      makeCandle({ time: i + 1 }),
    );
    const result = toLegacyMiniChartData(candles, 3, 10);
    expect(result).toHaveLength(3);
    expect(result[0]?.time).toBe(8);
  });

  it("falls back to fallbackCount when maxCandles is not finite", () => {
    const candles = Array.from({ length: 10 }, (_, i) =>
      makeCandle({ time: i + 1 }),
    );
    const result = toLegacyMiniChartData(candles, NaN, 5);
    expect(result).toHaveLength(5);
  });

  it("produces flat candle using last valid close for invalid candle", () => {
    const valid = makeCandle({ time: 1, close: 2.0 });
    const invalid = makeCandle({ time: 2, open: -1, close: -1 });
    const result = toLegacyMiniChartData([valid, invalid], 10, 10);
    // Second candle should be flat at last valid close = 2.0
    expect(result).toHaveLength(2);
    expect(result[1]?.close).toBe(2.0);
    expect(result[1]?.high).toBe(2.0);
  });

  it("flat-fills leading invalid candles using the next valid close", () => {
    // After the H1 pre-scan fix, seedLastValidClose() looks ahead so the leading
    // invalid candle is flat-filled with the first valid close found in the slice,
    // rather than dropped. Both entries are preserved.
    const invalid = makeCandle({ time: 1, open: -1, close: -1 });
    const valid = makeCandle({ time: 2 });
    const result = toLegacyMiniChartData([invalid, valid], 10, 10);
    expect(result).toHaveLength(2);
    expect(result[0]?.time).toBe(1);
    expect(result[0]?.close).toBe(valid.close); // flat-filled with next valid close
    expect(result[1]?.time).toBe(2);
  });
});

describe("createLegacyMiniChartOptions", () => {
  it("returns an object with the supplied width and height", () => {
    const opts = createLegacyMiniChartOptions(320, 120);
    expect(opts.width).toBe(320);
    expect(opts.height).toBe(120);
  });

  it("disables crosshair (mode 0)", () => {
    const opts = createLegacyMiniChartOptions(100, 100);
    expect(opts.crosshair?.mode).toBe(0);
  });

  it("keeps the right price scale visible so candles stop short of the label band", () => {
    // R289: rightPriceScale.visible must be TRUE so lightweight-charts
    // reserves the right-edge band where the DOM price-label pills sit —
    // without it, candles render under the pills (operator: "as velas tão
    // invadindo onde era o campo dos valores"). The dashed-line gap is
    // bridged by a DOM continuation strip behind the pills.
    const opts = createLegacyMiniChartOptions(320, 180);

    expect(opts.rightPriceScale?.visible).toBe(true);
    expect(opts.rightPriceScale?.borderVisible).toBe(false);
    // scaleMargins compressed to bottom=0.06 / top=0.02 (R29x): operator
    // pediu labels o mais próximo do topo possível; 2% mantém colchão
    // para o wick não clipar. Mantém parity com src/components/trade/
    // trade-card-mini-chart-core.ts:legacyMiniPriceScaleOptions.
    expect(opts.rightPriceScale?.scaleMargins).toEqual({
      bottom: 0.06,
      top: 0.02,
    });
    expect(opts.timeScale?.rightOffset).toBe(0.6);
  });

  it("keeps the right price scale visible when active trade fills horizontal space", () => {
    const opts = createLegacyMiniChartOptions(320, 180, {
      fillHorizontalSpace: true,
    });

    expect(opts.rightPriceScale?.visible).toBe(true);
    expect(opts.rightPriceScale?.borderVisible).toBe(false);
    expect(opts.timeScale?.barSpacing).toBe(10);
    expect(opts.timeScale?.rightOffset).toBe(0.6);
  });
});

describe("hasCompleteMiniChartData", () => {
  it("returns false when data length is below the threshold", () => {
    const data = Array.from({ length: 5 }, (_, i) =>
      makeCandle({ time: i + 1 }),
    );
    const rendered = toLegacyMiniChartData(data, 50, 50);
    expect(hasCompleteMiniChartData(rendered, 10)).toBe(false);
  });

  it("returns true when data length equals the threshold", () => {
    const data = Array.from({ length: 10 }, (_, i) =>
      makeCandle({ time: i + 1 }),
    );
    const rendered = toLegacyMiniChartData(data, 50, 50);
    expect(hasCompleteMiniChartData(rendered, 10)).toBe(true);
  });

  it("returns true when data length exceeds the threshold", () => {
    const data = Array.from({ length: 30 }, (_, i) =>
      makeCandle({ time: i + 1 }),
    );
    const rendered = toLegacyMiniChartData(data, 50, 50);
    expect(hasCompleteMiniChartData(rendered, 10)).toBe(true);
  });
});

describe("createLegacyMiniSeriesOptions", () => {
  it("returns an object with upColor and downColor defined", () => {
    const opts = createLegacyMiniSeriesOptions();
    expect(typeof opts.upColor).toBe("string");
    expect(typeof opts.downColor).toBe("string");
  });

  it("keeps the native current line but lets DOM labels own last value text", () => {
    const opts = createLegacyMiniSeriesOptions();
    expect(opts.priceLineVisible).toBe(true);
    expect(opts.lastValueVisible).toBe(false);
  });
});

