import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { act, renderHook } from "@testing-library/react";
import { useGoptionLiveCandles } from "@/features/trade/hooks";
import { resolveLiveCandleSeedUpdate } from "@/features/trade/live-candles";
import {
  FakeMatrixEventSource,
  useFakeEventSource,
} from "../../_fakes/event-source";
import type { ChartCandle } from "@/features/trade/types";

let eventSourceSwap: ReturnType<typeof useFakeEventSource>;

function seedCandle(): ChartCandle {
  return {
    time: 1_700_000_000,
    open: 3000,
    high: 3000,
    low: 3000,
    close: 3000,
    value: 3000,
  };
}

function seedCandles(count: number): ChartCandle[] {
  return Array.from({ length: count }, (_, index) => ({
    ...seedCandle(),
    time: seedCandle().time + index * 60,
    close: seedCandle().close + index,
    high: seedCandle().high + index,
    low: seedCandle().low + index,
    open: seedCandle().open + index,
    value: seedCandle().value + index,
  }));
}

beforeEach(() => {
  eventSourceSwap = useFakeEventSource();
});

afterEach(() => {
  eventSourceSwap.restore();
});

describe("useGoptionLiveCandles", () => {
  it("normalizes short ETH asset before opening broker stream and accepting ticks", () => {
    const initialCandles = seedCandles(30);
    const { result } = renderHook(() =>
      useGoptionLiveCandles("eth", true, {
        initialCandles,
        intervalSeconds: 60,
        maxCandles: 30,
      }),
    );
    const source = FakeMatrixEventSource.instances[0];
    expect(source?.url).toContain("/api/v2/market/stream/ETHUSDT");

    act(() => {
      source?.dispatchTick({
        symbol: "ETHUSDT",
        close: 3012,
        time: 1_700_000_020,
      });
    });

    expect(result.current.lastPrice).toBe(3012);
    expect(result.current.candles.at(-1)?.close).toBe(3012);
  });

  it("keeps one broker stream alive while hidden-tab ticks keep updating candles", () => {
    const initialCandles = seedCandles(30);
    const { result } = renderHook(() =>
      useGoptionLiveCandles("BTCUSDT", true, {
        initialCandles,
        intervalSeconds: 60,
        maxCandles: 30,
      }),
    );
    const source = FakeMatrixEventSource.instances[0];

    act(() => {
      document.dispatchEvent(new Event("visibilitychange"));
      source?.dispatchTick({
        symbol: "BTCUSDT",
        close: 64_512,
        time: 1_700_000_030,
      });
    });

    expect(FakeMatrixEventSource.instances).toHaveLength(1);
    expect(source?.readyState).toBe(1);
    expect(result.current.lastPrice).toBe(64_512);
    expect(result.current.candles.at(-1)?.close).toBe(64_512);
  });
});

describe("useGoptionLiveCandles — reload session seed", () => {
  it("starts persisting reload seed when preservation toggles on", () => {
    const initialCandles = seedCandles(30);
    const { rerender } = renderHook(
      ({ preserveReloadSeed }: { readonly preserveReloadSeed: boolean }) =>
        useGoptionLiveCandles("BTCUSDT", true, {
          initialCandles,
          intervalSeconds: 60,
          maxCandles: 30,
          preserveReloadSeed,
        }),
      { initialProps: { preserveReloadSeed: false } },
    );
    expect(liveCandleSessionKeys()).toHaveLength(0);
    rerender({ preserveReloadSeed: true });
    dispatchLatestTick();
    expect(liveCandleSessionKeys()).toHaveLength(1);
  });
});

// P0-103 regression suite kept separate so the parent describe stays under
// the 50-line per-function lint cap.
describe("useGoptionLiveCandles — partial-history SSE behavior", () => {
  it("opens the broker stream while Matrix history is empty", () => {
    const { result } = renderHook(() =>
      useGoptionLiveCandles("BTCUSDT", true, {
        intervalSeconds: 60,
        maxCandles: 30,
      }),
    );
    expect(result.current.candles).toHaveLength(0);
    expect(FakeMatrixEventSource.instances).toHaveLength(1);
    expect(result.current.lastPrice).toBeNull();
    expect(result.current.candles).toHaveLength(0);
  });

  it("opens the broker stream for short Matrix history", () => {
    // After `extendSeedToCurrentBucket` (28/05/2026): seed of 1 historical
    // candle gets a synthetic bucket-current candle appended on cold start,
    // so the rendered count is 2. Older "1" expectation predated the
    // instant-paint TradingView pattern.
    const initialCandles = seedCandles(1);
    const { result } = renderHook(() =>
      useGoptionLiveCandles("BTCUSDT", true, {
        initialCandles,
        intervalSeconds: 60,
        maxCandles: 30,
      }),
    );
    expect(FakeMatrixEventSource.instances).toHaveLength(1);
    expect(result.current.lastPrice).toBeNull();
    expect(result.current.candles).toHaveLength(2);
  });

  it("keeps the broker stream when Matrix history becomes complete", () => {
    const { result, rerender } = renderHook(
      (initialCandles: readonly ChartCandle[]) =>
        useGoptionLiveCandles("BTCUSDT", true, {
          initialCandles,
          intervalSeconds: 60,
          maxCandles: 30,
        }),
      { initialProps: seedCandles(1) },
    );
    expect(FakeMatrixEventSource.instances).toHaveLength(1);
    rerender(seedCandles(30));
    expect(FakeMatrixEventSource.instances).toHaveLength(1);
    expect(result.current.candles).toHaveLength(30);
  });

  it("keeps a stable 30-candle buffer when Matrix refetch returns empty", () => {
    const initialCandles = seedCandles(30);
    const { result, rerender } = renderHook(
      (candles: readonly ChartCandle[] | undefined) => {
        const options =
          candles === undefined
            ? { intervalSeconds: 60, maxCandles: 30 }
            : { initialCandles: candles, intervalSeconds: 60, maxCandles: 30 };
        return useGoptionLiveCandles("BTCUSDT", true, options);
      },
      { initialProps: initialCandles },
    );
    expect(result.current.candles).toHaveLength(30);
    rerender([]);
    expect(result.current.candles).toHaveLength(30);
  });

  it("keeps a stable 30-candle buffer when Matrix refetch returns short history", () => {
    const initialCandles = seedCandles(30);
    const { result, rerender } = renderHook(
      (candles: readonly ChartCandle[]) =>
        useGoptionLiveCandles("BTCUSDT", true, {
          initialCandles: candles,
          intervalSeconds: 60,
          maxCandles: 30,
        }),
      { initialProps: initialCandles },
    );
    expect(result.current.candles).toHaveLength(30);
    rerender(seedCandles(10));
    expect(result.current.candles).toHaveLength(30);
  });

  it("keeps a stable 30-candle buffer when Matrix refetch shortens to 20", () => {
    const initialCandles = seedCandles(30);
    const { result, rerender } = renderHook(
      (candles: readonly ChartCandle[]) =>
        useGoptionLiveCandles("BTCUSDT", true, {
          initialCandles: candles,
          intervalSeconds: 60,
          maxCandles: 30,
        }),
      { initialProps: initialCandles },
    );
    rerender(seedCandles(20));
    expect(result.current.candles).toHaveLength(30);
  });

  it("updates the last historical candle instead of collapsing to one candle", () => {
    const initialCandles = seedCandles(30);
    const { result } = renderHook(() =>
      useGoptionLiveCandles("BTCUSDT", true, {
        initialCandles,
        intervalSeconds: 60,
        maxCandles: 30,
      }),
    );
    const source = FakeMatrixEventSource.instances[0];
    const lastTime = initialCandles.at(-1)!.time;
    act(() =>
      source?.dispatchTick({
        symbol: "BTCUSDT",
        close: 78_820.0,
        time: lastTime + 1,
      }),
    );
    expect(result.current.candles).toHaveLength(30);
    expect(result.current.candles.at(-1)).toMatchObject({
      close: 78_820.0,
      high: 78_820.0,
    });
  });
});

function dispatchLatestTick(): void {
  const source = FakeMatrixEventSource.instances[0];
  act(() => {
    source?.dispatchTick({
      symbol: "BTCUSDT",
      close: 3_200,
      time: seedCandle().time + 59,
    });
  });
}

function liveCandleSessionKeys(): string[] {
  return Object.keys(window.sessionStorage).filter((key) =>
    key.startsWith("quartel.live-candles.v1"),
  );
}

describe("resolveLiveCandleSeedUpdate", () => {
  it("keeps stable history when a Matrix refetch returns no candles", () => {
    const decision = resolveLiveCandleSeedUpdate(seedCandles(30), [], 30, 30);
    expect(decision.kind).toBe("keep");
  });

  it("keeps stable history when a Matrix refetch returns fewer than full history", () => {
    const decision = resolveLiveCandleSeedUpdate(
      seedCandles(30),
      seedCandles(14),
      30,
      30,
    );
    expect(decision.kind).toBe("keep");
  });

  it("keeps SSE-folded tail when a Matrix refetch returns the previous same-size candle", () => {
    const current = seedCandles(30);
    const refetch = seedCandles(30);
    current[29] = { ...current[29]!, close: 76_042.14, value: 76_042.14 };
    const decision = resolveLiveCandleSeedUpdate(current, refetch, 30, 30);
    expect(decision.kind).toBe("keep");
  });

  it("replaces unstable short history with a healthier Matrix refetch", () => {
    const decision = resolveLiveCandleSeedUpdate(
      seedCandles(3),
      seedCandles(30),
      30,
      30,
    );
    expect(decision).toMatchObject({
      kind: "replace",
      candles: expect.any(Array),
    });
    if (decision.kind !== "replace")
      throw new Error(`decision=${decision.kind}, expected replace`);
    expect(decision.candles).toHaveLength(30);
  });

  it("respects the configured max candle cap when replacing history", () => {
    const decision = resolveLiveCandleSeedUpdate([], seedCandles(40), 30, 30);
    if (decision.kind !== "replace")
      throw new Error(`decision=${decision.kind}, expected replace`);
    expect(decision.candles).toHaveLength(30);
    expect(decision.candles[0]?.time).toBe(seedCandles(40)[10]?.time);
  });

  it("replaces unstable short history with a longer partial refetch", () => {
    const decision = resolveLiveCandleSeedUpdate(
      seedCandles(3),
      seedCandles(20),
      30,
      30,
    );
    if (decision.kind !== "replace")
      throw new Error(`decision=${decision.kind}, expected replace`);
    expect(decision.candles).toHaveLength(20);
  });
});

// Legacy parity tests for useGoptionLiveCandles bootstrap (P4 Track E slice γ).
//
// Pins three contract behaviors that match legacy
// `quartel-bot/lib/charts/use-mini-trade-chart-series-data-sync.ts:96`
// (MIN_CANDLES_FOR_TRADE_CHART = 3):
// 1. Hook returns the seed immediately at the 3-candle minimum (no buffering).
// 2. SSE subscription opens whenever symbol+enabled, even with seed length < 30.
// 3. First tick extends the buffer (3 → 4) instead of wiping to 0.
//
// Slice β changes the production hook to lift the live-seed gate. Until that
// lands, all three cases fail.
//
// TODO: blocked on slice ε — fakes import path. The named fakes
// `FakeMatrixEventSource` + `useFakeEventSource` live in
// `tests/unit/_fakes/event-source.ts` (slice ε). When ε merges, this import
// resolves; until then `pnpm typecheck` errors here.
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { act, renderHook } from "@testing-library/react";
import {
  FakeMatrixEventSource,
  useFakeEventSource,
} from "../../_fakes/event-source";
import { useGoptionLiveCandles } from "@/features/trade/hooks";
import type { ChartCandle } from "@/features/trade/types";

function buildSeedCandles(
  count: number,
  startTime = 1_777_280_400,
): ChartCandle[] {
  return Array.from({ length: count }, (_, i) => ({
    time: startTime + i * 60,
    open: 64000 + i,
    high: 64020 + i,
    low: 63980 + i,
    close: 64010 + i,
    value: 64010 + i,
  }));
}

function buildTickPayload(
  time: number,
  close: number,
  symbol = "BTCUSDT",
): string {
  return JSON.stringify({
    symbol,
    time,
    open: close,
    high: close,
    low: close,
    close,
  });
}

let eventSourceSwap: ReturnType<typeof useFakeEventSource>;

beforeEach(() => {
  FakeMatrixEventSource.reset();
  eventSourceSwap = useFakeEventSource();
});

afterEach(() => {
  eventSourceSwap.restore();
});

describe("useGoptionLiveCandles legacy bootstrap (threshold 3)", () => {
  it("returns_seed_immediately_at_min_threshold", () => {
    // After `extendSeedToCurrentBucket` (28/05/2026): the seed of 3 fixed
    // historical candles always gets a synthetic bucket-current candle
    // appended on cold start, so the hook returns 4 candles (3 seed + 1
    // synthetic). Older "3" expectation predated TradingView-style instant
    // paint and is now obsolete.
    const initialCandles = buildSeedCandles(3);
    const { result } = renderHook(() =>
      useGoptionLiveCandles("BTCUSDT", true, {
        initialCandles,
        intervalSeconds: 60,
        maxCandles: 30,
      }),
    );
    expect(result.current.candles).toHaveLength(4);
  });

  it("opens_sse_when_enabled_and_symbol", () => {
    const initialCandles = buildSeedCandles(3);
    renderHook(() =>
      useGoptionLiveCandles("BTCUSDT", true, {
        initialCandles,
        intervalSeconds: 60,
        maxCandles: 30,
      }),
    );
    expect(FakeMatrixEventSource.instances.length).toBe(1);
  });

  it("first_tick_extends_buffer_not_wipes", () => {
    // Same as above: seed=3 historical -> 4 with synthetic. First tick
    // either updates the synthetic in-place (same bucket) or appends a new
    // bucket. Use a tick aligned to the current bucket so it folds into
    // the synthetic and the array length stays at 4.
    const initialCandles = buildSeedCandles(3);
    const lastSeed = initialCandles[2]!;
    const { result } = renderHook(() =>
      useGoptionLiveCandles("BTCUSDT", true, {
        initialCandles,
        intervalSeconds: 60,
        maxCandles: 30,
      }),
    );
    expect(result.current.candles).toHaveLength(4);
    const source = FakeMatrixEventSource.instances[0]!;
    // Tick in the bucket of the current synthetic candle. Use the
    // synthetic's time (last entry in the candle buffer) as the bucket.
    const synthetic = result.current.candles[3]!;
    act(() => {
      source.dispatchRaw(
        "market:update",
        buildTickPayload(synthetic.time, lastSeed.close + 5),
      );
    });
    expect(result.current.candles).toHaveLength(4);
    // Tick that advances ONE bucket past the synthetic should append.
    act(() => {
      source.dispatchRaw(
        "market:update",
        buildTickPayload(synthetic.time + 60, lastSeed.close + 10),
      );
    });
    expect(result.current.candles).toHaveLength(5);
  });
});

