import { describe, expect, it } from "vitest";
import {
  appendTickToLiveCandles,
  hasCompleteLiveCandleSeed,
  normalizeBrokerSymbol,
  parseGoptionTick,
  resolveLiveCandleSeedUpdate,
  seedCompleteLiveCandles,
  seedLiveCandles,
  type GoptionTick,
} from "@/features/trade/live-candles";
import type { ChartCandle } from "@/features/trade/types";

// Shared builders for the buffer-gate describe block below
function buildLiveCandles(count: number): ChartCandle[] {
  return Array.from({ length: count }, (_, i) => ({
    time: 1_777_280_400 + i * 60,
    open: 64000 + i,
    high: 64020 + i,
    low: 63980 + i,
    close: 64010 + i,
    value: 64010 + i,
  }));
}

function fakeTick(): GoptionTick {
  return { symbol: "BTCUSDT", close: 64500, time: 1_777_280_400 + 99 * 60 };
}

const ALIGNED_BASE_TIME = 1_700_000_040;

function candleAt(index: number): ChartCandle {
  const value = 100 + index;
  return {
    time: ALIGNED_BASE_TIME + index * 60,
    open: value - 0.2,
    high: value + 0.5,
    low: value - 0.5,
    close: value,
    value,
  };
}

function tickAt(time: number, close: number): GoptionTick {
  return { symbol: "BTCUSDT", close, time };
}

describe("live candle helpers", () => {
  it("seeds the same legacy history window without mutating source candles", () => {
    const source = Array.from({ length: 55 }, (_, index) => candleAt(index));
    const seeded = seedLiveCandles(source, 50);
    expect(seeded).toHaveLength(50);
    expect(seeded[0]?.time).toBe(source[5]?.time);
    expect(seeded[0]).not.toBe(source[5]);
  });

  it("builds the first live candle when Matrix history is empty", () => {
    const candles = appendTickToLiveCandles(
      [],
      tickAt(1_700_000_060, 101),
      60,
      50,
    );
    expect(candles).toHaveLength(1);
    expect(candles[0]).toMatchObject({ close: 101, open: 101 });
  });

  // New behavior (MIN_CANDLES_FOR_TRADE_CHART = 3, P4 β/δ): a 1-candle seed is enough
  // to accept a tick — the buffer extends rather than returning [].
  it("accepts live ticks with a 1-candle seed (new 3-candle threshold)", () => {
    const source = Array.from({ length: 1 }, (_, index) => candleAt(index));
    const candles = appendTickToLiveCandles(
      source,
      tickAt(1_700_000_060, 101),
      60,
      3,
    );
    // Buffer should extend (not empty) once the seed is non-empty and maxCandles allows it.
    expect(candles.length).toBeGreaterThan(0);
  });

  it("copies partial historical seeds without a minimum gate", () => {
    const source = Array.from({ length: 3 }, (_, index) => candleAt(index));
    expect(seedCompleteLiveCandles(source.slice(0, 2), 3, 3)).toHaveLength(2);
    expect(seedCompleteLiveCandles(source, 3, 3)).toHaveLength(3);
    expect(hasCompleteLiveCandleSeed(source, 3)).toBe(true);
  });

  it("updates the active candle and keeps the broker history cap", () => {
    const source = Array.from({ length: 3 }, (_, index) => candleAt(index));
    const candles = appendTickToLiveCandles(
      source,
      tickAt(ALIGNED_BASE_TIME + 120, 104),
      60,
      3,
    );
    expect(candles).toHaveLength(3);
    expect(candles[2]).toMatchObject({
      close: 104,
      high: 104,
      low: source[2]?.low,
    });
  });

  it("appends a new bucket candle and evicts the oldest candle over cap", () => {
    const source = Array.from({ length: 3 }, (_, index) => candleAt(index));
    const nextBucket = ALIGNED_BASE_TIME + 180;
    const candles = appendTickToLiveCandles(
      source,
      tickAt(nextBucket, 108),
      60,
      3,
    );
    expect(candles).toHaveLength(3);
    expect(candles[0]?.time).toBe(source[1]?.time);
    expect(candles[2]).toMatchObject({
      close: 108,
      high: 108,
      low: 108,
      open: source[2]?.close,
    });
  });

  it("ignores out-of-order streaming ticks instead of appending stale candles", () => {
    const source = Array.from({ length: 3 }, (_, index) => candleAt(index));
    const staleTick = tickAt(ALIGNED_BASE_TIME + 60, 199);
    const candles = appendTickToLiveCandles(source, staleTick, 60, 3);
    expect(candles).toHaveLength(3);
    expect(candles.map((candle) => candle.time)).toEqual(
      source.map((candle) => candle.time),
    );
    expect(candles[2]?.close).toBe(source[2]?.close);
  });

  it("patches a synthetic current tail with the first delayed broker tick", () => {
    const historical = [candleAt(0), candleAt(1)];
    const syntheticTail = {
      ...candleAt(8),
      open: historical[1]!.close,
      high: historical[1]!.close,
      low: historical[1]!.close,
      close: historical[1]!.close,
      value: historical[1]!.close,
    };
    const candles = appendTickToLiveCandles(
      [...historical, syntheticTail],
      tickAt(ALIGNED_BASE_TIME + 30, 188),
      60,
      3,
    );
    expect(candles.at(-1)).toMatchObject({ time: syntheticTail.time });
    expect(candles.at(-1)).toMatchObject({ close: 188, high: 188 });
  });

  it("merges a late REST seed without dropping the current live candle", () => {
    const restSeed = Array.from({ length: 30 }, (_, index) => candleAt(index));
    const liveTail = [
      candleAt(27),
      candleAt(28),
      {
        ...candleAt(30),
        close: 140,
        high: 140,
        value: 140,
      },
    ];
    const decision = resolveLiveCandleSeedUpdate(liveTail, restSeed, 30);
    expect(decision.kind).toBe("replace");
    if (decision.kind !== "replace") return;
    expect(decision.candles).toHaveLength(30);
    expect(decision.candles.at(-1)).toMatchObject({
      time: candleAt(30).time,
      close: 140,
    });
    expect(decision.candles.at(-2)?.time).toBe(candleAt(29).time);
  });

  it("keeps painted closed candles when a stale refetch lands behind live tail", () => {
    const restSeed = Array.from({ length: 30 }, (_, index) => candleAt(index));
    const staleRefetch = restSeed.map((candle, index) =>
      index === 28 ? { ...candle, close: 999, high: 999, value: 999 } : candle,
    );
    const liveBuffer = [
      ...restSeed.slice(1, 30),
      { ...candleAt(30), close: 188, high: 188, value: 188 },
    ];

    const decision = resolveLiveCandleSeedUpdate(liveBuffer, staleRefetch, 30);

    expect(decision.kind).toBe("replace");
    if (decision.kind !== "replace") return;
    expect(
      decision.candles.find((candle) => candle.time === candleAt(28).time),
    ).toMatchObject({ close: candleAt(28).close });
    expect(decision.candles.at(-1)).toMatchObject({ close: 188 });
  });

  it("keeps a varied live window when F5 refetch returns flat candles", () => {
    const variedWindow = Array.from({ length: 30 }, (_, index) =>
      candleAt(index),
    );
    const flatReload = variedWindow.map((candle) => ({
      ...candle,
      close: 777,
      high: 777,
      low: 777,
      open: 777,
      value: 777,
    }));

    const decision = resolveLiveCandleSeedUpdate(variedWindow, flatReload, 30);

    expect(decision.kind).toBe("keep");
  });
});

describe("live candle F5 reload regressions", () => {
  it("keeps varied history even when a flat F5 refetch advances the tail", () => {
    const variedWindow = Array.from({ length: 30 }, (_, index) =>
      candleAt(index),
    );
    const flatReload = Array.from({ length: 30 }, (_, index) => ({
      close: 777,
      high: 777,
      low: 777,
      open: 777,
      time: candleAt(index + 1).time,
      value: 777,
    }));

    const decision = resolveLiveCandleSeedUpdate(variedWindow, flatReload, 30);

    expect(decision.kind).toBe("keep");
  });

  it("returns an empty replace decision when no seed or current buffer exists", () => {
    const decision = resolveLiveCandleSeedUpdate([], [], 30);
    expect(decision).toEqual({ kind: "replace", candles: [] });
  });

  it("replaces a flat current window when Matrix reload has real variation", () => {
    const flatCurrent = Array.from({ length: 30 }, (_, index) => ({
      ...candleAt(index),
      close: 777,
      high: 777,
      low: 777,
      open: 777,
      value: 777,
    }));
    const variedReload = Array.from({ length: 30 }, (_, index) =>
      candleAt(index),
    );

    const decision = resolveLiveCandleSeedUpdate(flatCurrent, variedReload, 30);

    expect(decision.kind).toBe("replace");
    if (decision.kind !== "replace") return;
    expect(decision.candles.at(-1)).toEqual(variedReload.at(-1));
  });
});

describe("live candle helpers", () => {
  it("drops current candles older than a stale refetch window", () => {
    const restSeed = Array.from({ length: 5 }, (_, index) => candleAt(index));
    const liveBuffer = [
      { ...candleAt(-1), close: 999, high: 999, value: 999 },
      ...restSeed.slice(0, 2),
      { ...candleAt(5), close: 188, high: 188, value: 188 },
    ];

    const decision = resolveLiveCandleSeedUpdate(liveBuffer, restSeed, 10);

    expect(decision.kind).toBe("replace");
    if (decision.kind !== "replace") return;
    expect(
      decision.candles.some((candle) => candle.time === candleAt(-1).time),
    ).toBe(false);
    expect(decision.candles.at(-1)).toMatchObject({ close: 188 });
  });

  it("keeps a live-updated tail when REST returns the same timestamp", () => {
    const restSeed = Array.from({ length: 5 }, (_, index) => candleAt(index));
    const live = restSeed.map((candle) => ({ ...candle }));
    const tail = live[4];
    if (!tail) throw new Error("Expected live[4] to exist in 5-candle seed");
    live[4] = { ...tail, close: 130, high: 130, value: 130 };
    const decision = resolveLiveCandleSeedUpdate(live, restSeed, 5);
    expect(decision.kind).toBe("keep");
  });

  it("keeps a live-updated close even when the wick did not expand", () => {
    const restSeed = Array.from({ length: 5 }, (_, index) => candleAt(index));
    const live = restSeed.map((candle) => ({ ...candle }));
    const tail = live[4];
    if (!tail) throw new Error("Expected live[4] to exist in 5-candle seed");
    live[4] = { ...tail, close: tail.close + 0.1, value: tail.close + 0.1 };
    const decision = resolveLiveCandleSeedUpdate(live, restSeed, 5);
    expect(decision.kind).toBe("keep");
  });

  it("keeps a live-expanded high wick on the same timestamp", () => {
    const restSeed = Array.from({ length: 5 }, (_, index) => candleAt(index));
    const live = restSeed.map((candle) => ({ ...candle }));
    const tail = live[4];
    if (!tail) throw new Error("Expected live[4] to exist in 5-candle seed");
    live[4] = { ...tail, high: tail.high + 3 };
    const decision = resolveLiveCandleSeedUpdate(live, restSeed, 5);
    expect(decision.kind).toBe("keep");
  });

  it("keeps a live-expanded low wick on the same timestamp", () => {
    const restSeed = Array.from({ length: 5 }, (_, index) => candleAt(index));
    const live = restSeed.map((candle) => ({ ...candle }));
    const tail = live[4];
    if (!tail) throw new Error("Expected live[4] to exist in 5-candle seed");
    live[4] = { ...tail, low: tail.low - 3 };
    const decision = resolveLiveCandleSeedUpdate(live, restSeed, 5);
    expect(decision.kind).toBe("keep");
  });

  it("lets same-tail refetches update older closed candles", () => {
    const current = Array.from({ length: 5 }, (_, index) => candleAt(index));
    const refetch = current.map((candle, index) =>
      index === 3 ? { ...candle, close: 444, high: 444, value: 444 } : candle,
    );

    const decision = resolveLiveCandleSeedUpdate(current, refetch, 5);

    expect(decision.kind).toBe("replace");
    if (decision.kind !== "replace") return;
    expect(decision.candles[3]).toMatchObject({ close: 444 });
  });

  it("accepts a newer REST seed instead of preserving stale current candles", () => {
    const current = Array.from({ length: 5 }, (_, index) => candleAt(index));
    const staleCurrent = current.map((candle, index) =>
      index === 4 ? { ...candle, close: 333, high: 333, value: 333 } : candle,
    );
    const refetch = Array.from({ length: 5 }, (_, index) =>
      candleAt(index + 1),
    );

    const decision = resolveLiveCandleSeedUpdate(staleCurrent, refetch, 5);

    expect(decision.kind).toBe("replace");
    if (decision.kind !== "replace") return;
    expect(decision.candles.at(-2)).toMatchObject({ close: candleAt(4).close });
    expect(decision.candles.at(-1)).toMatchObject({ close: candleAt(5).close });
  });

  it("keeps the live buffer when a refetch shrinks the Matrix history", () => {
    const current = Array.from({ length: 30 }, (_, index) => candleAt(index));
    const shortRefetch = Array.from({ length: 12 }, (_, index) =>
      candleAt(index),
    );
    const decision = resolveLiveCandleSeedUpdate(current, shortRefetch, 30);
    expect(decision.kind).toBe("keep");
  });

  it("replaces an unchanged same-size refetch instead of taking the shrink branch", () => {
    const current = Array.from({ length: 5 }, (_, index) => candleAt(index));
    const refetch = Array.from({ length: 5 }, (_, index) => candleAt(index));
    const decision = resolveLiveCandleSeedUpdate(current, refetch, 5);
    expect(decision.kind).toBe("replace");
  });

  it("keeps current tail candles at the seed boundary and sorts newer tail", () => {
    const restSeed = Array.from({ length: 30 }, (_, index) => candleAt(index));
    const boundary = { ...candleAt(29), close: 177, high: 177, value: 177 };
    const newer = { ...candleAt(30), close: 188, high: 188, value: 188 };
    const newest = { ...candleAt(31), close: 199, high: 199, value: 199 };
    const decision = resolveLiveCandleSeedUpdate(
      [newest, newer, boundary],
      restSeed,
      30,
    );
    expect(decision.kind).toBe("replace");
    if (decision.kind !== "replace") return;
    expect(decision.candles.at(-3)).toMatchObject({
      time: boundary.time,
      close: 177,
    });
    expect(decision.candles.at(-2)?.time).toBe(newer.time);
    expect(decision.candles.at(-1)?.time).toBe(newest.time);
  });

  it("parses GOption ticks and broker symbols strictly", () => {
    const tick = parseGoptionTick(
      '{"symbol":"BTCUSDT","close":76269.22,"time":1777280400,"is_closed":true}',
    );
    expect(tick).toMatchObject({
      symbol: "BTCUSDT",
      close: 76269.22,
      isClosed: true,
    });
    expect(normalizeBrokerSymbol("btc")).toBe("BTCUSDT");
    expect(normalizeBrokerSymbol("ETHUSDT")).toBe("ETHUSDT");
    expect(
      parseGoptionTick('{"symbol":"BTCUSDT","close":"bad","time":1}'),
    ).toBeNull();
    expect(parseGoptionTick("{not json")).toBeNull();
  });

  it("normalizes millisecond websocket tick timestamps to candle seconds", () => {
    const tick = parseGoptionTick(
      '{"symbol":"BTCUSDT","close":76269.22,"time":1777280400123}',
    );
    expect(tick).toMatchObject({
      symbol: "BTCUSDT",
      close: 76269.22,
      time: 1_777_280_400,
    });
  });
});

describe("buffer-gate invariants", () => {
  // P4: the live buffer accepts ticks even before Matrix history arrives.
  it("appendTickToLiveCandles extends empty and partial buffers", () => {
    const emptyResult = appendTickToLiveCandles([], fakeTick(), 60, 3);
    expect(emptyResult).toHaveLength(1);

    for (let prevLen = 1; prevLen < 3; prevLen += 1) {
      const prev = buildLiveCandles(prevLen);
      const result = appendTickToLiveCandles(prev, fakeTick(), 60, 3);
      expect(result.length, `prevLen=${prevLen}`).toBeGreaterThan(0);
    }

    // prev.length=3: full seed, definitely extends.
    const fullPrev = buildLiveCandles(3);
    const fullResult = appendTickToLiveCandles(fullPrev, fakeTick(), 60, 3);
    expect(fullResult.length).toBeGreaterThan(0);
  });

  const seedBoundaryCases = [
    { seedLen: 0, min: 1, expected: 0 },
    { seedLen: 0, min: 3, expected: 0 },
    { seedLen: 2, min: 3, expected: 2 },
    { seedLen: 3, min: 3, expected: 3 },
    { seedLen: 4, min: 3, expected: 3 }, // capped at maxCandles=3
  ];

  it.each(seedBoundaryCases)(
    "seedCompleteLiveCandles boundary table: seedLen=$seedLen min=$min → $expected",
    ({ seedLen, min, expected }) => {
      const result = seedCompleteLiveCandles(buildLiveCandles(seedLen), 3, min);
      expect(result.length).toBe(expected);
    },
  );
});

