import { describe, it, expect } from "vitest";
import {
  appendTickToLiveCandles,
  bufferPendingTick,
  extendSeedToCurrentBucket,
  replayBufferedTicks,
  resolveLiveCandleSeedUpdate,
  type GoptionTick,
} from "./live-candles";
import {
  computeEntryAwareYRange,
  shouldExpandLockedYRange,
} from "./entry-aware-y-range";
import type { ChartCandle } from "./types";

type CandleOhlc = {
  readonly time: number;
  readonly open: number;
  readonly high: number;
  readonly low: number;
  readonly close: number;
};

function candle(
  ...args: [number, number, number, number, number] | [CandleOhlc]
): ChartCandle {
  const [first] = args;
  const ohlc: CandleOhlc =
    typeof first === "number"
      ? {
          time: args[0] as number,
          open: args[1] as number,
          high: args[2] as number,
          low: args[3] as number,
          close: args[4] as number,
        }
      : first;
  return { ...ohlc, value: ohlc.close };
}

describe("appendTickToLiveCandles", () => {
  it("expande high/low ao receber tick maior/menor dentro do bucket", () => {
    const prev = [candle(60, 1980, 1980, 1980, 1980)];
    const afterUp = appendTickToLiveCandles(
      prev,
      { symbol: "ETHUSDT", close: 1985, time: 60 },
      60,
      30,
    );
    expect(afterUp[0]).toMatchObject({ high: 1985, low: 1980, close: 1985 });

    const afterDown = appendTickToLiveCandles(
      afterUp,
      { symbol: "ETHUSDT", close: 1978, time: 60 },
      60,
      30,
    );
    expect(afterDown[0]).toMatchObject({ high: 1985, low: 1978, close: 1978 });
  });
});

describe("extendSeedToCurrentBucket", () => {
  it("anexa vela synthetic no bucket corrente quando histórico está velho", () => {
    // Histórico termina em t=60. Bucket corrente t=240. Synthetic deve ser
    // criada em t=240 com open=close=high=low igual ao close anterior.
    const seed = [candle(60, 1978, 1981, 1977, 1980)];
    const result = extendSeedToCurrentBucket(seed, 60, 30, 240);
    expect(result).toHaveLength(2);
    expect(result[1]).toMatchObject({
      time: 240,
      open: 1980,
      high: 1980,
      low: 1980,
      close: 1980,
    });
  });

  it("não modifica quando bucket corrente coincide com último candle", () => {
    const seed = [candle(60, 1978, 1981, 1977, 1980)];
    const result = extendSeedToCurrentBucket(seed, 60, 30, 60);
    expect(result).toHaveLength(1);
    expect(result[0]).toEqual(seed[0]);
  });

  it("respeita cap maxCandles ao adicionar synthetic", () => {
    // 30 candles + 1 synthetic = 31, cap em 30 → primeira sai.
    const seed = Array.from({ length: 30 }, (_, i) =>
      candle(60 + i * 60, 1980, 1981, 1979, 1980),
    );
    const result = extendSeedToCurrentBucket(seed, 60, 30, 60 + 30 * 60);
    expect(result).toHaveLength(30);
    expect(result[29]).toMatchObject({ time: 60 + 30 * 60, open: 1980 });
  });

  it("retorna array vazio quando seed vazio", () => {
    expect(extendSeedToCurrentBucket([], 60, 30, 240)).toEqual([]);
  });
});

describe("appendTickToLiveCandles — padrão TradingView", () => {
  // Padrão oficial: gap-in-time é invisível pelo logical range; gap-in-price
  // é fechado abrindo a nova vela em last.close. Não backfillar para evitar
  // que velas antigas saiam pelo cap maxCandles e causem scroll lateral.
  it("emite UMA vela nova quando bucket avança em vários buckets (sem backfill)", () => {
    const prev = [candle(60, 1978, 1981, 1977, 1980)];
    const result = appendTickToLiveCandles(
      prev,
      { symbol: "ETHUSDT", close: 1982, time: 240 },
      60,
      30,
    );
    expect(result).toHaveLength(2);
    expect(result[1]).toMatchObject({
      time: 240,
      open: 1980,
      high: 1982,
      low: 1982,
      close: 1982,
    });
  });

  it("emite vela no próximo bucket abrindo no close anterior", () => {
    const prev = [candle(60, 1978, 1981, 1977, 1980)];
    const result = appendTickToLiveCandles(
      prev,
      { symbol: "ETHUSDT", close: 1981, time: 120 },
      60,
      30,
    );
    expect(result).toHaveLength(2);
    expect(result[1]).toMatchObject({ time: 120, open: 1980, close: 1981 });
  });
});

function tick(time: number, close: number): GoptionTick {
  return { symbol: "ETHUSDT", time, close };
}

describe("bufferPendingTick — snapshot+delta queue", () => {
  it("buffer durante REST: anexa ticks em ordem cronológica", () => {
    let buffer: readonly GoptionTick[] = [];
    buffer = bufferPendingTick(buffer, tick(60, 1980));
    buffer = bufferPendingTick(buffer, tick(61, 1981));
    buffer = bufferPendingTick(buffer, tick(62, 1982));
    expect(buffer.map((t) => t.time)).toEqual([60, 61, 62]);
    expect(buffer.map((t) => t.close)).toEqual([1980, 1981, 1982]);
  });

  it("dedup por tick.time: tick mais novo no mesmo bucket substitui o antigo", () => {
    let buffer: readonly GoptionTick[] = [];
    buffer = bufferPendingTick(buffer, tick(60, 1980));
    buffer = bufferPendingTick(buffer, tick(60, 1985));
    expect(buffer).toHaveLength(1);
    expect(buffer[0]).toMatchObject({ time: 60, close: 1985 });
  });

  it("ticks fora de ordem são inseridos cronologicamente (defensivo)", () => {
    let buffer: readonly GoptionTick[] = [];
    buffer = bufferPendingTick(buffer, tick(62, 1982));
    buffer = bufferPendingTick(buffer, tick(60, 1980));
    buffer = bufferPendingTick(buffer, tick(61, 1981));
    expect(buffer.map((t) => t.time)).toEqual([60, 61, 62]);
  });

  it("respeita maxBuffer cap (FIFO eviction)", () => {
    let buffer: readonly GoptionTick[] = [];
    for (let t = 1; t <= 10; t += 1) {
      buffer = bufferPendingTick(buffer, tick(t, 1980 + t), 5);
    }
    expect(buffer).toHaveLength(5);
    expect(buffer[0]?.time).toBe(6);
    expect(buffer[4]?.time).toBe(10);
  });
});

describe("replayBufferedTicks — snapshot+delta replay", () => {
  it("replay após REST: ordem dos ticks preservada, último close vence no bucket", () => {
    // Seed pintado com vela synthetic em t=60.
    const seed: ChartCandle[] = [candle(60, 1980, 1980, 1980, 1980)];
    // Ticks bufferizados durante REST: 3 ticks no mesmo bucket t=60,
    // depois 1 tick que avança o bucket para t=120.
    const buffered: GoptionTick[] = [
      tick(60, 1982),
      tick(60, 1985),
      tick(60, 1981),
      tick(120, 1990),
    ];
    const result = replayBufferedTicks(seed, buffered, 60, 30);
    expect(result).toHaveLength(2);
    // Bucket 60 deve ter consolidado high=1985 (wick maior), low=1980,
    // close=1981 (último tick antes do bucket pivot).
    expect(result[0]).toMatchObject({
      time: 60,
      open: 1980,
      high: 1985,
      low: 1980,
      close: 1981,
    });
    // Bucket 120 abre no close do bucket anterior (1981) e fecha em 1990.
    expect(result[1]).toMatchObject({
      time: 120,
      open: 1981,
      high: 1990,
      low: 1990,
      close: 1990,
    });
  });

  it("replay vazio retorna seed inalterada", () => {
    const seed: ChartCandle[] = [candle(60, 1980, 1981, 1979, 1980)];
    const result = replayBufferedTicks(seed, [], 60, 30);
    expect(result).toEqual(seed);
    // Defensive: result must be a fresh array (no aliasing).
    expect(result).not.toBe(seed);
  });

  it("replay com seed vazio + buffer não vazio cria velas a partir do primeiro tick", () => {
    const buffered: GoptionTick[] = [tick(60, 1980), tick(120, 1985)];
    const result = replayBufferedTicks([], buffered, 60, 30);
    expect(result).toHaveLength(2);
    expect(result[0]?.time).toBe(60);
    expect(result[1]?.time).toBe(120);
  });
});

describe("computeEntryAwareYRange — Y-scale lock com entry line inclusa", () => {
  it("inclui entryPrice ABAIXO do candle range no min", () => {
    const candles: ChartCandle[] = [
      candle(60, 2000, 2010, 1995, 2005),
      candle(120, 2005, 2012, 2000, 2008),
    ];
    const range = computeEntryAwareYRange(candles, 1980, 0.04);
    expect(range).not.toBeNull();
    // min deve ser <= 1980 (entry) menos padding.
    expect(range!.minValue).toBeLessThan(1980);
    // max deve ser >= 2012 (high) mais padding.
    expect(range!.maxValue).toBeGreaterThan(2012);
  });

  it("inclui entryPrice ACIMA do candle range no max", () => {
    const candles: ChartCandle[] = [candle(60, 2000, 2010, 1995, 2005)];
    const range = computeEntryAwareYRange(candles, 2050, 0.04);
    expect(range).not.toBeNull();
    expect(range!.maxValue).toBeGreaterThan(2050);
    expect(range!.minValue).toBeLessThan(1995);
  });

  it("padding ~4% sobre o range expandido", () => {
    // Range largo o suficiente para 4% domine o price-floor (0.08% do max).
    const candles: ChartCandle[] = [candle(60, 1500, 2000, 1500, 1900)];
    const range = computeEntryAwareYRange(candles, 1900, 0.04);
    // expanded range = [1500, 2000], width=500, pad = 500 * 0.04 = 20.
    // floor = 2000 * 0.0008 = 1.6 (não domina). Resultado: [1480, 2020].
    expect(range!.minValue).toBeCloseTo(1480, 0);
    expect(range!.maxValue).toBeCloseTo(2020, 0);
  });

  it("retorna null para seed vazio sem entry", () => {
    expect(computeEntryAwareYRange([], null, 0.04)).toBeNull();
  });

  it("usa price-floor quando candles e entry colapsam num único valor", () => {
    // Mercado flat: todas as velas no mesmo preço, sem padding por range.
    const flat: ChartCandle[] = [
      candle(60, 2000, 2000, 2000, 2000),
      candle(120, 2000, 2000, 2000, 2000),
    ];
    const range = computeEntryAwareYRange(flat, 2000, 0.04);
    // Floor pad = max * 0.0008 = 2000 * 0.0008 = 1.6.
    expect(range!.maxValue - range!.minValue).toBeGreaterThan(0);
    expect(range!.maxValue - range!.minValue).toBeCloseTo(3.2, 1);
  });

  it("calcula range só por candles quando entry está ausente", () => {
    const candles: ChartCandle[] = [candle(60, 2000, 2010, 1990, 2005)];
    const range = computeEntryAwareYRange(candles, null, 0);
    expect(range).toEqual({ minValue: 1988.392, maxValue: 2011.608 });
  });

  it("calcula range só pela entry quando ainda não há candles", () => {
    const range = computeEntryAwareYRange([], 2000, 0.04);
    expect(range).toEqual({ minValue: 1998.4, maxValue: 2001.6 });
  });

  it("ignora candles com high ou low não finitos", () => {
    const range = computeEntryAwareYRange(
      [
        candle({
          time: 60,
          open: 2000,
          high: Number.NaN,
          low: 1990,
          close: 2000,
        }),
        candle({
          time: 120,
          open: 2000,
          high: 2010,
          low: Number.NaN,
          close: 2000,
        }),
      ],
      null,
    );
    expect(range).toBeNull();
  });
});

describe("shouldExpandLockedYRange — re-expand quando preço escapa", () => {
  it("KEEP quando preço está dentro do inner 90% do range", () => {
    const range = { minValue: 1900, maxValue: 2100 }; // width=200, inner=[1910,2090]
    expect(shouldExpandLockedYRange(range, 2000)).toBe(false);
  });

  it("EXPAND quando preço entra na margem 5% superior", () => {
    const range = { minValue: 1900, maxValue: 2100 };
    expect(shouldExpandLockedYRange(range, 2095)).toBe(true);
  });

  it("EXPAND quando preço entra na margem 5% inferior", () => {
    const range = { minValue: 1900, maxValue: 2100 };
    expect(shouldExpandLockedYRange(range, 1905)).toBe(true);
  });

  it("EXPAND quando preço escapa completamente do range", () => {
    const range = { minValue: 1900, maxValue: 2100 };
    expect(shouldExpandLockedYRange(range, 2200)).toBe(true);
    expect(shouldExpandLockedYRange(range, 1800)).toBe(true);
  });

  it("KEEP quando preço é NaN ou infinito (defensivo)", () => {
    const range = { minValue: 1900, maxValue: 2100 };
    expect(shouldExpandLockedYRange(range, Number.NaN)).toBe(false);
    expect(shouldExpandLockedYRange(range, Number.POSITIVE_INFINITY)).toBe(
      false,
    );
  });

  it("EXPAND quando range travado colapsa", () => {
    expect(
      shouldExpandLockedYRange({ minValue: 2000, maxValue: 2000 }, 2000),
    ).toBe(true);
  });

  it("KEEP nas bordas exatas do inner range", () => {
    const range = { minValue: 1900, maxValue: 2100 };
    expect(shouldExpandLockedYRange(range, 1910)).toBe(false);
    expect(shouldExpandLockedYRange(range, 2090)).toBe(false);
  });

  it("respeita innerRatio customizado ao calcular margem", () => {
    const range = { minValue: 1900, maxValue: 2100 };
    expect(shouldExpandLockedYRange(range, 1960, 0.5)).toBe(false);
    expect(shouldExpandLockedYRange(range, 1940, 0.5)).toBe(true);
  });
});

describe("resolveLiveCandleSeedUpdate — wick protection", () => {
  it("mantém o estado atual quando Matrix snapshot retorna wick mais curto", () => {
    // SSE expandiu high pra 1985 entre dois polls do Matrix; snapshot vem
    // só com 1983 no high.
    const liveWithWick = [candle(60, 1980, 1985, 1980, 1983)];
    const matrixSnapshot = [candle(60, 1980, 1983, 1980, 1983)];
    const decision = resolveLiveCandleSeedUpdate(
      liveWithWick,
      matrixSnapshot,
      30,
    );
    expect(decision.kind).toBe("keep");
  });

  it("mantém o estado atual quando Matrix snapshot tem low mais alto", () => {
    const liveWithWick = [candle(60, 1980, 1983, 1976, 1981)];
    const matrixSnapshot = [candle(60, 1980, 1983, 1980, 1981)];
    const decision = resolveLiveCandleSeedUpdate(
      liveWithWick,
      matrixSnapshot,
      30,
    );
    expect(decision.kind).toBe("keep");
  });

  it("substitui quando Matrix snapshot avança no tempo", () => {
    const liveOld = [candle(60, 1980, 1985, 1980, 1983)];
    const matrixNewer = [
      candle(60, 1980, 1985, 1980, 1983),
      candle(120, 1983, 1984, 1982, 1984),
    ];
    const decision = resolveLiveCandleSeedUpdate(liveOld, matrixNewer, 30);
    expect(decision.kind).toBe("replace");
  });
});

