import { beforeEach, describe, expect, it } from "vitest";
import {
  liveCandleSessionKey,
  readLiveCandleSessionSeed,
  selectLiveCandleReloadSeed,
  writeLiveCandleSessionSeed,
} from "@/features/trade/live-candle-session-cache";
import type { ChartCandle } from "@/features/trade/types";

const KEY = liveCandleSessionKey("BTCUSDT", 60, 30);

function candleAt(index: number): ChartCandle {
  const close = 64000 + index * 5;
  return {
    close,
    high: close + 4,
    low: close - 4,
    open: close - 2,
    time: 1_777_280_400 + index * 60,
    value: close,
  };
}

function flatCandles(count: number): ChartCandle[] {
  return Array.from({ length: count }, (_, index) => ({
    close: 64000,
    high: 64000,
    low: 64000,
    open: 64000,
    time: 1_777_280_400 + index * 60,
    value: 64000,
  }));
}

describe("live candle session cache", () => {
  beforeEach(() => {
    window.sessionStorage.clear();
  });

  it("persists only varied reload seeds for the current tab", () => {
    writeLiveCandleSessionSeed(
      KEY,
      [candleAt(0), candleAt(1), candleAt(2)],
      10,
    );
    const seed = readLiveCandleSessionSeed(KEY, 20);
    expect(seed).toHaveLength(3);
    expect(seed[0]).toEqual(candleAt(0));
  });

  it("builds distinct keys per symbol interval and cap", () => {
    expect(liveCandleSessionKey("BTCUSDT", 60, 30)).toBe(
      "quartel.live-candles.v1:BTCUSDT:60:30",
    );
    expect(liveCandleSessionKey("ETHUSDT", 60, 30)).not.toBe(KEY);
    expect(liveCandleSessionKey("BTCUSDT", 1, 30)).not.toBe(KEY);
    expect(liveCandleSessionKey("BTCUSDT", 60, 50)).not.toBe(KEY);
  });

  it("does not overwrite a healthy seed with a flat reload window", () => {
    writeLiveCandleSessionSeed(
      KEY,
      [candleAt(0), candleAt(1), candleAt(2)],
      10,
    );
    writeLiveCandleSessionSeed(KEY, flatCandles(30), 20);
    expect(readLiveCandleSessionSeed(KEY, 30).at(-1)).toEqual(candleAt(2));
  });

  it("drops expired seeds instead of reviving stale charts", () => {
    writeLiveCandleSessionSeed(
      KEY,
      [candleAt(0), candleAt(1), candleAt(2)],
      10,
    );
    expect(readLiveCandleSessionSeed(KEY, 130_011)).toEqual([]);
  });

  it("keeps a seed fresh through the exact TTL boundary", () => {
    writeLiveCandleSessionSeed(
      KEY,
      [candleAt(0), candleAt(1), candleAt(2)],
      10,
    );
    expect(readLiveCandleSessionSeed(KEY, 120_010)).toHaveLength(3);
    expect(readLiveCandleSessionSeed(KEY, 120_011)).toEqual([]);
  });

  it("prefers session seed when reload data is flat", () => {
    const sessionSeed = [candleAt(0), candleAt(1), candleAt(2)];
    expect(selectLiveCandleReloadSeed(flatCandles(30), sessionSeed)).toBe(
      sessionSeed,
    );
  });

  it("does not revive a session seed when Matrix returns an empty window", () => {
    const sessionSeed = [candleAt(0), candleAt(1), candleAt(2)];
    expect(selectLiveCandleReloadSeed([], sessionSeed)).toEqual([]);
  });

  it("prefers fresh Matrix reload data over the previous session seed", () => {
    const matrixSeed = [candleAt(3), candleAt(4), candleAt(5)];
    const sessionSeed = [candleAt(0), candleAt(1), candleAt(2)];
    expect(selectLiveCandleReloadSeed(matrixSeed, sessionSeed)).toBe(
      matrixSeed,
    );
  });

  it("removes malformed session payloads before they can seed a chart", () => {
    const malformedPayloads = [
      null,
      { version: 2, storedAtMs: 10, candles: [candleAt(0)] },
      { version: 1, storedAtMs: Number.NaN, candles: [candleAt(0)] },
      { version: 1, storedAtMs: 10, candles: [candleAt(0), {}] },
      { version: 1, storedAtMs: 10, candles: [partialCandle()] },
    ];
    for (const payload of malformedPayloads) {
      window.sessionStorage.setItem(KEY, JSON.stringify(payload));
      expect(readLiveCandleSessionSeed(KEY, 20)).toEqual([]);
      expect(window.sessionStorage.getItem(KEY)).toBeNull();
    }
  });
});

function partialCandle(): Record<string, number> {
  return { close: 10, high: 11, low: 9, open: 10, time: 1 };
}

