import { describe, expect, it } from "vitest";
import {
  LEGACY_ACTIVE_TRADE_COUNTBACK,
  LEGACY_ACTIVE_TRADE_CANDLES,
  stableActiveTradeCandles,
  stableTerminalTradeCandles,
  hasCompleteRobotTradeCandles,
  hasCompleteRobotTradeHistory,
} from "@/features/robot/components/flow/robot-legacy-trade-gates";
import type { ChartCandle } from "@/features/trade/types";

function buildChartCandles(
  count: number,
  startTime = 1_777_280_400,
): ChartCandle[] {
  return Array.from({ length: count }, (_, i) => ({
    time: startTime + i * 60,
    open: 64000 + i * 7,
    high: 64020 + i * 7,
    low: 63980 + i * 7,
    close: 64010 + i * 7,
    value: 64010 + i * 7,
  }));
}

function buildFlatChartCandles(count: number): ChartCandle[] {
  return Array.from({ length: count }, (_, i) => ({
    time: 1_777_280_400 + i * 60,
    open: 64000,
    high: 64000,
    low: 64000,
    close: 64000,
    value: 64000,
  }));
}

describe("hasCompleteRobotTradeHistory", () => {
  it("threshold at 50", () => {
    expect(hasCompleteRobotTradeHistory(buildChartCandles(49))).toBe(false);
    expect(hasCompleteRobotTradeHistory(buildChartCandles(50))).toBe(true);
    expect(hasCompleteRobotTradeHistory(buildChartCandles(51))).toBe(true);
    expect(LEGACY_ACTIVE_TRADE_COUNTBACK).toBe(50);
  });
});

describe("hasCompleteRobotTradeCandles", () => {
  it("threshold at 3 normalized candles", () => {
    expect(hasCompleteRobotTradeCandles(buildChartCandles(2))).toBe(false);
    expect(hasCompleteRobotTradeCandles(buildChartCandles(3))).toBe(true);
    expect(hasCompleteRobotTradeCandles(buildChartCandles(29))).toBe(true);
    expect(LEGACY_ACTIVE_TRADE_CANDLES).toBe(30);
  });

  it("returns false when 30 input candles all have invalid close", () => {
    // Candles with negative values fail isPositiveMiniCandle; no valid close
    // to fall back to, so toLegacyMiniChartData drops them all.
    const invalid = Array.from(
      { length: 30 },
      (_, i): ChartCandle => ({
        time: 1_777_280_400 + i * 60,
        open: -1,
        high: -1,
        low: -2,
        close: -1,
        value: -1,
      }),
    );
    expect(hasCompleteRobotTradeCandles(invalid)).toBe(false);
  });

  it("returns true when 30 valid candles after normalization", () => {
    expect(hasCompleteRobotTradeCandles(buildChartCandles(30))).toBe(true);
  });

  it("returns false when 30 input candles collapse to one timestamp", () => {
    const duplicated = buildChartCandles(30).map((candle) => ({
      ...candle,
      time: 1_777_280_400,
    }));
    expect(hasCompleteRobotTradeCandles(duplicated)).toBe(false);
  });

  it("returns false when F5 reload returns 30 flat candles", () => {
    expect(hasCompleteRobotTradeCandles(buildFlatChartCandles(30))).toBe(false);
  });
});

describe("stableActiveTradeCandles", () => {
  it("returns [] when both inputs short", () => {
    const result = stableActiveTradeCandles([], buildChartCandles(2));
    expect(result).toEqual([]);
  });

  it("returns sliced last-30 of fallback when fallback complete and live empty", () => {
    const fallback = buildChartCandles(50);
    const result = stableActiveTradeCandles([], fallback);
    expect(result).toHaveLength(30);
    expect(result[0]?.time).toBe(fallback[20]?.time);
  });

  it("returns live values when live complete (>=30)", () => {
    const live = buildChartCandles(30);
    const fallback = buildChartCandles(50);
    const result = stableActiveTradeCandles(live, fallback);
    expect(result).toEqual(live);
  });

  it("returns live values after the 3-candle first-paint threshold", () => {
    const live = buildChartCandles(3);
    const fallback = buildChartCandles(50);
    const result = stableActiveTradeCandles(live, fallback);
    expect(result).toEqual(live);
  });

  it("falls back to varied history when the live reload window is flat", () => {
    const fallback = buildChartCandles(50);
    const result = stableActiveTradeCandles(
      buildFlatChartCandles(30),
      fallback,
    );
    expect(result).toHaveLength(30);
    expect(result[0]?.time).toBe(fallback[20]?.time);
  });

  const liveLengths = [0, 1, 29, 30, 31];
  const fallbackLengths = [0, 1, 29, 30, 49, 50, 51];
  const cases = liveLengths.flatMap((l) =>
    fallbackLengths.map((f) => ({ l, f })),
  );

  it.each(cases)(
    "matrix: live=$l fallback=$f → length is 0 or >=3",
    ({ l, f }) => {
      const result = stableActiveTradeCandles(
        buildChartCandles(l),
        buildChartCandles(f),
      );
      expect(result.length === 0 || result.length >= 3).toBe(true);
    },
  );
});

describe("stableTerminalTradeCandles", () => {
  it("returns [] when fallback short", () => {
    const result = stableTerminalTradeCandles(buildChartCandles(49));
    expect(result).toEqual([]);
  });

  it("returns fallback values when complete", () => {
    const fallback = buildChartCandles(50);
    const result = stableTerminalTradeCandles(fallback);
    expect(result).toEqual(fallback);
  });
});

