import { describe, expect, it } from "vitest";
import {
  candleWindowEnvelope,
  hasMeaningfulCandleVariation,
  type CandleWindowPoint,
} from "@/features/trade/candle-window-quality";

function variedCandle(index: number): CandleWindowPoint {
  const close = 100 + index;
  return {
    close,
    high: close + 0.2,
    low: close - 0.2,
    open: close - 0.1,
  };
}

function flatCandle(): CandleWindowPoint {
  return { close: 100, high: 100, low: 100, open: 100 };
}

function highPriceCandle(offset: number): CandleWindowPoint {
  const price = 1_000_000_000;
  return {
    close: price + offset,
    high: price + offset,
    low: price,
    open: price,
  };
}

describe("hasMeaningfulCandleVariation", () => {
  it("rejects a reload window where every candle collapsed to one price", () => {
    expect(
      hasMeaningfulCandleVariation([flatCandle(), flatCandle(), flatCandle()]),
    ).toBe(false);
  });

  it("accepts a three-candle legacy first-paint window with real OHLC span", () => {
    const candles = [variedCandle(0), variedCandle(1), variedCandle(2)];
    expect(hasMeaningfulCandleVariation(candles)).toBe(true);
  });

  it("requires the full requested window before accepting variation", () => {
    expect(hasMeaningfulCandleVariation([variedCandle(0)], 3)).toBe(false);
    expect(hasMeaningfulCandleVariation([variedCandle(0)], Number.NaN)).toBe(
      true,
    );
  });

  it("uses only the configured trailing candle window", () => {
    const candles = [variedCandle(0), flatCandle(), flatCandle()];
    expect(hasMeaningfulCandleVariation(candles, 2)).toBe(false);
    expect(hasMeaningfulCandleVariation(candles, 3)).toBe(true);
  });

  it("rejects non-finite price bounds", () => {
    const bad = [{ ...variedCandle(0), high: Number.NaN }];
    expect(candleWindowEnvelope(bad)).toBeNull();
  });

  it("ignores one malformed candle without poisoning the remaining envelope", () => {
    const envelope = candleWindowEnvelope([
      { ...variedCandle(0), open: Number.NaN },
      variedCandle(4),
    ]);
    expect(envelope?.referencePrice).toBe(104.2);
    expect(envelope?.span).toBeCloseTo(0.4, 6);
  });

  it("rejects tiny apparent movement on high-price assets", () => {
    const candles = [
      highPriceCandle(0),
      highPriceCandle(0.0001),
      highPriceCandle(0.0002),
    ];
    expect(hasMeaningfulCandleVariation(candles)).toBe(false);
  });

  it("computes the envelope from every OHLC bound", () => {
    const envelope = candleWindowEnvelope([
      { close: 105, high: 110, low: 100, open: 102 },
      { close: 98, high: 99, low: 95, open: 97 },
    ]);
    expect(envelope).toEqual({ referencePrice: 110, span: 15 });
  });
});

