// Legacy parity tests for robot trade chart gates (P4 Track E slice γ).
//
// Mirrors `activeTradeChartGates.legacy.test.ts`: the visible robot active
// card first-paints at 3 candles so live trades do not keep a blank chart.
import { describe, expect, it } from "vitest";
import {
  MIN_TRADE_CHART_CANDLES,
  hasCompleteRobotTradeCandles,
  stableActiveTradeCandles,
} from "@/features/robot/components/flow/robot-legacy-trade-gates";
import type { ChartCandle } from "@/features/trade/types";

function buildChartCandles(
  count: number,
  startTime = 1_777_280_400,
): ChartCandle[] {
  return Array.from({ length: count }, (_, i) => ({
    time: startTime + i * 60,
    open: 64000 + i * 7,
    high: 64020 + i * 7,
    low: 63980 + i * 7,
    close: 64010 + i * 7,
    value: 64010 + i * 7,
  }));
}

describe("MIN_TRADE_CHART_CANDLES (robot gates)", () => {
  it("equals legacy threshold of 3 candles", () => {
    expect(MIN_TRADE_CHART_CANDLES).toBe(3);
  });
});

describe("hasCompleteRobotTradeCandles first-paint threshold", () => {
  it("returns false at length 2", () => {
    expect(hasCompleteRobotTradeCandles(buildChartCandles(2))).toBe(false);
  });

  it("returns true at length 3", () => {
    expect(hasCompleteRobotTradeCandles(buildChartCandles(3))).toBe(true);
  });

  it("returns true at length 29", () => {
    expect(hasCompleteRobotTradeCandles(buildChartCandles(29))).toBe(true);
  });
});

describe("stableActiveTradeCandles first-paint fallback selection", () => {
  it("returns live when live.length >= 3", () => {
    const live = buildChartCandles(3);
    const fallback = buildChartCandles(50);
    expect(stableActiveTradeCandles(live, fallback)).toEqual(live);
  });

  it("returns fallback tail when live.length < 3 and fallback complete", () => {
    const fallback = buildChartCandles(50);
    const result = stableActiveTradeCandles(buildChartCandles(2), fallback);
    expect(result.length).toBe(30);
  });

  it("returns live when live.length === 29 (above threshold)", () => {
    const live = buildChartCandles(29);
    const fallback = buildChartCandles(50);
    expect(stableActiveTradeCandles(live, fallback)).toEqual(live);
