// Legacy parity tests for the active trade chart gates (P4 Track E slice γ).
//
// Active-card first paint follows the legacy helper threshold of 3 candles so
// the chart does not stay blank while waiting for a complete 30-candle window.
import { describe, expect, it } from "vitest";
import {
  MIN_TRADE_CHART_CANDLES,
  activeTradeChartCandles,
  hasCompleteActiveTradeChart,
} from "@/features/trade/components/active-trade-chart-gates";
import type { ChartCandle } from "@/features/trade/types";

function buildChartCandles(
  count: number,
  startTime = 1_777_280_400,
): ChartCandle[] {
  return Array.from({ length: count }, (_, i) => ({
    time: startTime + i * 60,
    open: 64000 + i * 7,
    high: 64020 + i * 7,
    low: 63980 + i * 7,
    close: 64010 + i * 7,
    value: 64010 + i * 7,
  }));
}

describe("MIN_TRADE_CHART_CANDLES", () => {
  it("equals legacy threshold of 3 candles", () => {
    expect(MIN_TRADE_CHART_CANDLES).toBe(3);
  });
});

describe("hasCompleteActiveTradeChart first-paint threshold", () => {
  it("returns false at length 2", () => {
    expect(hasCompleteActiveTradeChart(buildChartCandles(2))).toBe(false);
  });

  it("returns true at length 3", () => {
    expect(hasCompleteActiveTradeChart(buildChartCandles(3))).toBe(true);
  });

  it("returns true at length 29", () => {
    expect(hasCompleteActiveTradeChart(buildChartCandles(29))).toBe(true);
  });
});

describe("activeTradeChartCandles first-paint fallback selection", () => {
  it("returns live when live.length >= 3", () => {
    const live = buildChartCandles(3);
    const fallback = buildChartCandles(50);
    expect(activeTradeChartCandles(live, fallback)).toEqual(live);
  });

  it("returns fallback tail when live.length < 3 and fallback complete", () => {
    const fallback = buildChartCandles(50);
    const result = activeTradeChartCandles(buildChartCandles(2), fallback);
    expect(result.length).toBe(30);
  });

  it("returns live when live.length === 29 (above threshold)", () => {
    const live = buildChartCandles(29);
    const fallback = buildChartCandles(50);
    expect(activeTradeChartCandles(live, fallback)).toEqual(live);
  });
});
